L4_1 = {}
L4_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 5500107
L4_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "그 뒤로 벌써 보름이나 지났는데, 본부에선 뭔가 알아낸 게 있나요?"
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "あれからもう半月経ちますが、本部の方では何か進展があったんでしょうか？"
L4_1.m_Talk_ENG = "It's been 2 weeks already. Has HQ found out anything yet?"
L4_1.m_Talk_TWN = "都已經過去半個月了，總部那邊都沒有什麼發現嗎？"
L4_1.m_Talk_THA = "นี่ก็ผ่านมาแล้ว 2 สัปดาห์ ศูนย์บัญชาการยังไม่มีรายงานความคืบหน้าอะไรเลยหรอ พวกนั้นมัวทำอะไรกันอยู่อะ?"
L4_1.m_Talk_VTN = "Cũng được 2 tuần rồi. Trụ Sở đã phát hiện ra điều gì chưa?"
L4_1.m_Talk_SCN = "都已经过去半个月了，总部那边就没有什么发现吗？"
L4_1.m_Talk_DEU = "Es sind schon zwei Wochen vergangen. Hat das Hauptquartier schon etwas herausgefunden?"
L4_1.m_Talk_FRA = "Ça fait déjà 2 semaines. Le quartier général a-t-il déjà découvert quelque chose ?"
L5_1 = {}
L5_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 5500107
L5_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_DESPAIR"
L5_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "아니요. 예상대로 우리 세계의 기술력으로는 프로텍트를 해제할 수 없는 모양이에요."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "いいえ。予想通り、私たちの世界の技術力ではプロテクトを解除することはできないようです。"
L5_1.m_Talk_ENG = "No. As we expected, it is impossible to disable the protection with our technology."
L5_1.m_Talk_TWN = "沒有，不出所料，以我們世界的技術還無法解除那些裝備上的防護器。"
L5_1.m_Talk_THA = "ไม่อะไรคืบหน้าเลย นี่ไม่เหมือนอย่างที่เราคิดไว้เลย ถ้ามันจะใช้เทคโนโลยีปกปิดมันไว้ก็เป็นไปไม่ได้ "
L5_1.m_Talk_VTN = "Chưa. Như chúng ta nghĩ, không thể tắt tính năng bảo vệ bằng công nghệ của chúng ta."
L5_1.m_Talk_SCN = "没有。跟预想的一样，以我们世界的技术还无法解除那些装备上的防护器。"
L5_1.m_Talk_DEU = "Nein. Wie erwartet ist es mit unserer Technologie nicht möglich, den Schutz zu deaktivieren."
L5_1.m_Talk_FRA = "Non. Comme nous nous y attendions, il est impossible de désactiver la barrière de protection avec notre technologie."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 5500107
L6_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_IDLE"
L6_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L6_1.m_Pos = "C"
L6_1.m_Talk_KOREA = "무기를 함선 밖으로 반출하면 즉시 분자단위로 분해되어 쓸 수 없다는 보고를 받았거든요."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "武器を艦船の外に搬出すると、すぐに分子単位に分解され、使えなくなるという報告を受けました。"
L6_1.m_Talk_ENG = "According to reports, the weapons disintegrate into atoms the moment they are taken outside of the ship."
L6_1.m_Talk_TWN = "而且我收到的報告說，若是將武器搬離艦船之外，會立刻分解成分子，無法使用。"
L6_1.m_Talk_THA = "จากรายงาน ที่รู้มาพวกอาวุธนั้นมันจะสลายตัวเองกลายเป็นอะตอม ทันทีที่ถูกนำออกมาจากยานนั่น"
L6_1.m_Talk_VTN = "Theo các báo cáo, vũ khí sẽ phân rã thành nguyên tử ngay khi chúng được đưa ra khỏi tàu."
L6_1.m_Talk_SCN = "并且我收到的报告说，若是将武器搬离舰船之外，会立刻分解成分子，无法使用。"
L6_1.m_Talk_DEU = "Berichten zufolge, werden die Waffen sofort in Moleküle zerfallen und somit komplett unbrauchbar, wenn sie aus dem Schiff entnommen werden."
L6_1.m_Talk_FRA = "Selon les rapports, les armes se désintègrent au niveau moléculaire dès lors qu'elles sont emmenées à l'extérieur du vaisseau."
L7_1 = {}
