L9_1 = {}
L9_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 5500107
L9_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_DESPAIR"
L9_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L9_1.m_Pos = "R"
L9_1.m_Talk_KOREA = "하아, 역시 일이 그렇게 잘 풀릴 리 없겠죠."
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "はぁ、やっぱりそう簡単にはいきませんよね。"
L9_1.m_Talk_ENG = "*Sigh...* I knew things weren't going to go so smoothly."
L9_1.m_Talk_TWN = "哈啊，果然事情不會那麼順利。"
L9_1.m_Talk_THA = "*เฮ่ย ถอนหายใจ...* ฉันคิดว่าต้องมีอะไรบางอย่าง ที่ไม่ค่อยปกติ"
L9_1.m_Talk_VTN = "*Thở dài...* Tôi biết mọi thứ sẽ không diễn ra suôn sẻ như vậy."
L9_1.m_Talk_SCN = "哈啊，果然事情不会那么顺利。"
L9_1.m_Talk_DEU = "*Seufz* Ich wusste, dass wir das Problem mit dem Schutz der Waffen nicht so einfach lösen werden."
L9_1.m_Talk_FRA = "*Soupir...* Je me doutais bien que les choses ne se passeraient pas comme prévu."
L10_1 = {}
L10_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 5500107
L10_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_IDLE"
L10_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L10_1.m_Pos = "R"
L10_1.m_Talk_KOREA = "그럼 결국 방법은 그 안토노프라는 분이 기억을 되찾는 수밖에 없겠네요."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "じゃあ結局、あのアントノフという人が記憶を取り戻すしか方法はないんですね。"
L10_1.m_Talk_ENG = "The only thing left is for Antonov to get her memories back."
L10_1.m_Talk_TWN = "那麼，只剩下讓那位名叫安東諾夫的人，找回記憶這一個辦法了。"
L10_1.m_Talk_THA = "ทางเดียวที่เหลืออยู่ก็คือทำให้ความทรงจำของแอนโทนอฟกลับมา"
L10_1.m_Talk_VTN = "Điều duy nhất còn lại là để Antonov lấy lại ký ức của cô ấy."
L10_1.m_Talk_SCN = "那么，只剩下让那位名叫安东的人，找回记忆这一个办法了。"
L10_1.m_Talk_DEU = "Das Einzige, was uns noch bleibt, ist, dass diese Person namens Antonow ihre Erinnerungen zurückerlangt."
L10_1.m_Talk_FRA = "La seule solution qu'il nous reste serait donc qu'Antonov récupère ses souvenirs."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 5500107
L11_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_IDLE"
L11_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L11_1.m_Pos = "L"
L11_1.m_Talk_KOREA = "그렇겠죠."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "そうですね。"
L11_1.m_Talk_ENG = "I suppose so."
L11_1.m_Talk_TWN = "沒錯。"
L11_1.m_Talk_THA = "ฉันเองก็คิดแบบนั้น"
L11_1.m_Talk_VTN = "Tôi cho là vậy."
L11_1.m_Talk_SCN = "没错。"
L11_1.m_Talk_DEU = "Ja, wir haben anscheinend keine andere Option."
L11_1.m_Talk_FRA = "Oui, j'imagine."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 5500107
L12_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L12_1.m_Pos = "L"
L12_1.m_Talk_KOREA = "따라서 당분간 제가 이곳 제7 방위선의 담당관이 되어, 그자를 내사하기로 결정했습니다."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "というわけで、当分は私がこの第7防衛線の担当官となり、彼女を内偵することにしました。"
L12_1.m_Talk_ENG = "So for the time being, I've decided to be in charge of the 7th Defense Line and investigate her myself."
L12_1.m_Talk_TWN = "所以我會臨時擔任第七防線的負責人，並且親自對她展開調查。"
L12_1.m_Talk_THA = "งั้น ฉันจะขอหน่วยป้องกันที่ 7 ในการขอสอบสวนเธอเอง"
L12_1.m_Talk_VTN = "Vì vậy, trong thời gian này, tôi đã quyết định phụ trách Phòng Tuyến số 7 và tự mình điều tra cô ấy."
L12_1.m_Talk_SCN = "所以我会临时担任第7防线的负责人，并且亲自对她展开调查。"
L12_1.m_Talk_DEU = "Also habe ich vorerst beschlossen, die Leitung der 7. Verteidigungslinie zu übernehmen und intern gegen sie zu ermitteln."
L12_1.m_Talk_FRA = "C'est pourquoi, pour le moment, j'ai décidé d'être en charge de la 7e ligne de défense et d'enquêter sur elle moi-même."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 5500107
L13_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_SURPRISE"
L13_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L13_1.m_Pos = "R"
L13_1.m_Talk_KOREA = "내사라고요? 사령 본부로 이송하지 않고?"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "内偵？　指令本部に移送するんじゃなくて？"
L13_1.m_Talk_ENG = "Investigate her yourself? Why not hand her over to HQ?"
L13_1.m_Talk_TWN = "親自調查？不把她移交給司令總部嗎？"
L13_1.m_Talk_THA = "เธอว่าไงนะคาริน เธอจะสอบสวนแอนโทนอฟเองหรอ? ทำไมไม่ส่งยัยนั้นไปที่ศูนย์บัญชาการล่ะ?"
L13_1.m_Talk_VTN = "Tự điều tra cô ấy? Tại sao không giao cô ấy cho Trụ Sở?"
L13_1.m_Talk_SCN = "亲自调查？不把她移交给司令总部吗？"
L13_1.m_Talk_DEU = "Intern gegen sie zu ermitteln? Warum übergibst du sie nicht einfach dem Hauptquartier?"
L13_1.m_Talk_FRA = "Enquêter sur elle par vous-même ? Pourquoi ne pas laisser le quartier général s'en occuper ?"
L14_1 = {}
L14_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 5500107
L14_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L14_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L14_1.m_Pos = "L"
L14_1.m_Talk_KOREA = "우린 아직 그자가 어떤 의도로 우리 세계로 왔는지 모릅니다. 기억을 잃었다는 것 자체가 우리를 기만하는 걸지도 모르죠."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "私たちはまだ彼女がなぜ私たちの世界に来たのかわかっていません。記憶喪失もただの嘘なのかもしれませんし。"
L14_1.m_Talk_ENG = "We have no idea what her intentions are for coming to this world. Plus, her amnesia could just be a ploy to make us lower our guards."
L14_1.m_Talk_TWN = "我們目前還不清楚，她是帶著什麼目的來到我們世界的。也許失憶這件事，本身就是個謊言。"
L14_1.m_Talk_THA = "นั้นเพราะเราไม่รู้เจตนาที่แท้จริงของเธอ บางครั้งการแกล้งความจำเสื่อมก็อาจเป็นเพียงกลลวงที่เธอสร้างขึ้น เพื่อหลอกให้พวกเราตายใจใครจะรู้?"
L14_1.m_Talk_VTN = "Chúng ta không biết ý định của cô ấy khi đến thế giới này là gì. Thêm nữa, chứng mất trí nhớ của cô ấy có thể chỉ là một trò để khiến chúng ta hạ thấp cảnh giác."
L14_1.m_Talk_SCN = "我们目前还不清楚，她是带着什么目的来到我们世界的。也许失忆这件事，本身就是个谎言。"
L14_1.m_Talk_DEU = "Wir wissen immer noch nicht, welche Absichten sie hatte, als sie in unsere Welt kam. Außerdem könnte ihr Gedächtnisverlust auch nur vorgetäuscht sein."
L14_1.m_Talk_FRA = "Nous n'avons aucune idée des intentions qui l'ont poussée à venir dans ce monde. De plus, son amnésie pourrait être un stratagème pour nous faire baisser notre garde."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "EXILER_ACT1_INTERUDE2@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 5500107
L15_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L15_1.m_Pos = "L"
L15_1.m_Talk_KOREA = "무엇보다도 그자에 관해서는 로스트 쉽이나 무기고 외에도 수상한 점이 많아요."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "なにより彼女に関しては、ロストシップや武器庫以外の点でも怪しいところが多いんです。"
L15_1.m_Talk_ENG = "But above all, there are many suspicious things about her other than the Lost Ship and the weapons."
L15_1.m_Talk_TWN = "最重要的是，除了與她相關的失落艦船和那些武器外，還有許多其他可疑的部分。"
L15_1.m_Talk_THA = "แต่ว่าไป ฉันเองก็สงสัยในตัวแอนโทนอฟอยู่นะ ทั้งเรื่องยานที่หายสาบสูญ และเรื่องอาวุธพวกนั้นด้วย"
L15_1.m_Talk_VTN = "Nhưng trên hết, có rất nhiều điều đáng ngờ về cô ấy ngoài Con tàu Thất Lạc và vũ khí."
L15_1.m_Talk_SCN = "最重要的是，除了与她相关的失落舰船和那些武器外，还有许多其他可疑的部分。"
L15_1.m_Talk_DEU = "Aber vor allem gibt es noch zu viele Ungereimtheiten, was sie angeht, mal ganz abgesehen von dem Verlorenen Schiff und den Waffen."
L15_1.m_Talk_FRA = "Mais surtout, outre le vaisseau perdu et les armes, il existe de nombreuses zones d'ombres à propos d'elle."
