L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "それ以外の怪しいところ？"
L16_1.m_Talk_ENG = "What are they?"
L16_1.m_Talk_TWN = "其他可疑的地方？"
L16_1.m_Talk_THA = "เธอสงสัยยัยนั่นอะไรหรอ?"
L16_1.m_Talk_VTN = "Là gì thế?"
L16_1.m_Talk_SCN = "其他可疑的地方？"
L16_1.m_Talk_DEU = "Was denn für Ungereimtheiten?"
L16_1.m_Talk_FRA = "Lesquelles ?"
