L18_1.m_CharScale = L19_1
L18_1.m_CharScaleTime = 0.01
L18_1.m_Talk_KOREA = "아시다시피 이면 세계든, 현실 세계든 각 세계 간에는 <color=#ffd34c>양자 위상의 차이</color>가 존재해요."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "ご存知のとおり、裏世界であれ現実世界であれ、世界と世界の間には<color=#ffd34c>量子位相のズレ</color>が存在します。"
L18_1.m_Talk_ENG = "As you know, there's a <color=#ffd34c>quantum phase difference</color> between worlds and even between Counterside and ours."
L18_1.m_Talk_TWN = "你也知道不管是異界還是現實世界，每個世界之間都存在<color=#ffd34c>量子能量差</color>。"
L18_1.m_Talk_THA = "คิดดีๆตามหลักแล้ว<color=#ffd34c> เฟสควอนตัมมีความแตกต่าง</color> ระหว่างโลกระหว่างเคาน์เตอร์ไซด์และเรา"
L18_1.m_Talk_VTN = "Như cô đã biết, có <color=#ffd34c>lệch pha lượng tử</color> giữa các thế giới và thậm chí giữa Counterside và thế giới của chúng ta."
L18_1.m_Talk_SCN = "你也知道不管是异界，还是现实世界，每个世界之间都存在<color=#ffd34c>量子能量差</color>。"
L18_1.m_Talk_DEU = "Wie du bereits weißt, gibt es einen <color=#ffd34c>Quantenphasenunterschied</color> zwischen den Welten und sogar zwischen Counterside und unserer Welt."
L18_1.m_Talk_FRA = "Comme vous le savez, il existe une <color=#ffd34c>différence de phase quantique</color> entre le Contremonde et le Vérimonde."
