L19_1.m_CharScale = L20_1
L19_1.m_CharScaleTime = 0.01
L19_1.m_Talk_KOREA = "이 법칙을 무시하면 얼마 안 가 물질의 구성 원소가 유지력을 잃고 완전히 분해되어버리죠."
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "この法則を無視すると、物質はやがて構成元素の維持力を失い、完全に分解されてしまいます。"
L19_1.m_Talk_ENG = "Ignoring this law will make any material lose its molecular structure and disintegrate."
L19_1.m_Talk_TWN = "如果無視這個規律，物質的構成元素很快就會失去穩定性，並完全分解掉。"
L19_1.m_Talk_THA = "ถ้าหากเราตัดทฤษฏีนั้นไป เมื่อวัตถุใดๆที่สูญเสียโครงสร้างโมเลกุลมันก็จะถูกสลายตัวไป"
L19_1.m_Talk_VTN = "Mặc kệ quy luật này sẽ làm cho bất kỳ vật chất nào cũng mất đi cấu trúc phân tử và tan rã."
L19_1.m_Talk_SCN = "如果无视这个规律，物质的构成元素很快就会失去稳定性，并完全分解掉。"
L19_1.m_Talk_DEU = "Wird dieses Gesetz missachtet, verlieren die Bestandteile des Materials innerhalb kürzester Zeit ihre molekulare Struktur und zerfallen."
L19_1.m_Talk_FRA = "Ignorer cette loi ferait perdre à n'importe quel matériau sa structure moléculaire et le ferait se désintégrer."
