L20_1.m_Talk_KOREA = "하지만 그 엑자일러는 어떻죠? "
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "しかしあのエグザイラーはどうでしょうか？ "
L20_1.m_Talk_ENG = "But, what about the Exile?"
L20_1.m_Talk_TWN = "但那個流浪者呢？"
L20_1.m_Talk_THA = "แล้วถ้าหากเธอคือผู้ถูกเนรเทศล่ะ?"
L20_1.m_Talk_VTN = "Nhưng còn Kẻ Lưu Vong kia thì sao?"
