L21_1.m_Talk_KOREA = "벌써 보름이나 지났는데 사라지지 않았잖아요."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "半月も経つのに、まだ消えていません。"
L21_1.m_Talk_ENG = "It's been over 2 weeks and she's still here."
L21_1.m_Talk_TWN = "已經過去半個月了，她卻沒有消失。"
L21_1.m_Talk_THA = "ผ่านมาแล้ว 2 สัปดาห์แล้ว เธอก็ยังอยู่ที่นี่"
L21_1.m_Talk_VTN = "Đã hơn 2 tuần trôi qua và cô ấy vẫn ở đây."
L21_1.m_Talk_SCN = "已经过去半个月了，但她却并没有消失。"
L21_1.m_Talk_DEU = "Es ist schon über zwei Wochen her und sie ist immer noch nicht verschwunden."
L21_1.m_Talk_FRA = "Cela fait plus de 2 semaines et elle est toujours là."
