L24_1.m_Crash = 20
L24_1.m_Talk_KOREA = "듣고 보니, 확실히 이상하네요."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "そう言われてみれば、確かに変ですね。"
L24_1.m_Talk_ENG = "Now that you mention it, that is certainly odd."
L24_1.m_Talk_TWN = "聽你這麼一說，確實有點可疑。"
L25_1 = "ถ้างั้น สิ่งที่เธอพูดถึง มันก็ค่อนข้างแปลก "
L24_1.m_Talk_THA = L25_1
L25_1 = "Giờ cô nói đến nó, thì mới thấy thật kỳ lạ."
L24_1.m_Talk_VTN = L25_1
L25_1 = "听你这么一说，确实有点可疑。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Jetzt, wo du es erwähnst, ist es definitiv seltsam."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Maintenant que vous le dites, c'est vrai que c'est étrange."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EXILER_ACT1_INTERUDE2@25#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 25
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 5500107
L25_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_IDLE"
L25_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L25_1.m_Pos = "R"
L26_1 = "그 말은 즉, 엑자일러가 다른 세계에 정착할 수 있다는 뜻이잖아요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "つまりそれは、エグザイラーが別の世界に定着することができるということを意味しますよね。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "That can only mean that Exiles can migrate to other worlds."
L25_1.m_Talk_ENG = L26_1
L26_1 = "你的意思就是，流浪者也可以在其他的世界定居。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "หมายความว่า มีแค่ผู้ถูกเนรเทศที่สามารถอพยพมายังโลกอื่นได้ เท่านั้น"
L25_1.m_Talk_THA = L26_1
L26_1 = "Điều đó chỉ có nghĩa là Kẻ Lưu Vong có thể di cư đến các thế giới khác."
L25_1.m_Talk_VTN = L26_1
L26_1 = "你的意思就是，流浪者也可以在其他的世界定居。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Das kann nur bedeuten, dass sich Exilanten in anderen Welten niederlassen können."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Ça veut sûrement dire que les exilés peuvent migrer vers d'autres mondes."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EXILER_ACT1_INTERUDE2@26#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 26
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5500107
L26_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_IDLE"
L26_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L26_1.m_Pos = "L"
L27_1 = "네, 틀림없이 그자는 우리보다 많은 걸 알고 있을 겁니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "はい、間違いなく彼女は私たちより多くのことを知っているはずです。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Yes. I'm sure that she knows more than we can ever imagine."
L26_1.m_Talk_ENG = L27_1
L27_1 = "沒錯。而且她知道的好像比我們更多。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ใช่ ฉันคิดว่าเธอต้องรู้อะไรมากกว่าที่เราสงสัย"
L26_1.m_Talk_THA = L27_1
L27_1 = "Đúng. Tôi chắc chắn rằng cô ấy biết nhiều hơn những gì chúng ta có thể tưởng tượng."
L26_1.m_Talk_VTN = L27_1
L27_1 = "没错。而且她知道的好像比我们更多。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ja. Ich bin sicher, dass sie mehr weiß als wir."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Oui. Je suis sûre qu'elle en sait plus que nous ne pourrons jamais l'imaginer."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EXILER_ACT1_INTERUDE2@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5500107
L27_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "UNIT_HATE"
L27_1.m_Face = L28_1
L27_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L27_1.m_Pos = "L"
L28_1 = "저는 무슨 짓을 해서라도 그자가 우리 세계에 온 목적을 알아내고야 말 겁니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "私は何としてでも、彼女が私たちの世界に来た目的を聞き出してみせます。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "My objective with her is to find out why she's here, no matter what it takes."
L27_1.m_Talk_ENG = L28_1
L28_1 = "無論如何，我都要弄清楚她來我們世界的目的。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "สิ่งเดียวคือถามจากปากเธอ แล้วหาคำตอบว่าทำไมเธอถึงมาที่นี่ ทั้งๆที่เธอก็รู้ว่าเอาอะไรติดตัวมาไม่ได้  "
L27_1.m_Talk_THA = L28_1
L28_1 = "Mục tiêu của tôi với cô ấy là tìm ra lý do cô ấy ở đây, bất kỳ giá nào."
L27_1.m_Talk_VTN = L28_1
L28_1 = "无论如何，我都要弄清楚她来我们世界的目的。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich werde alles tun, um herauszufinden, warum sie in unsere Welt gekommen ist."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Mon objectif est donc de découvrir pourquoi elle est ici, coûte que coûte."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
