L30_1 = "하지만 괜찮겠어요, 카린 양?"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "でも、そんなことをして大丈夫なんですか、カリンさん？"
L29_1.m_Talk_JPN = L30_1
L30_1 = "But are you sure about this, Karin?"
L29_1.m_Talk_ENG = L30_1
L30_1 = "你確定嗎，卡琳？"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ว่าแต่ เธอเองแน่ใจเรื่องนี้มากแค่ไหนน่ะ คาริน?"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nhưng cô chắc về điều này không, Karin?"
L29_1.m_Talk_VTN = L30_1
L30_1 = "你确定吗，卡琳？"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Aber bist du dir da ganz sicher, Karin?"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Vous êtes sûre que ça ira, Karin ?"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EXILER_ACT1_INTERUDE2@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 30
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5500107
L30_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L30_1.m_Pos = "C"
L31_1 = "아마도 그 안토노프라는 엑자일러, 다른 세계에선 델타 세븐의 대원이었던 것 같던데요?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "おそらくあのアントノフというエグザイラーは他の世界ではデルタセブンの隊員ですよ？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "That Exile, Antonov, looked like a member of Delta Seven from another world, no?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "也許那個叫做安東諾夫的流浪者，曾是其他世界第七三角洲部隊的隊員呢？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แอนโทนอฟ คือผู้ถูกเนรเทศ และเป็นสมาชิกของเดลต้าเซเว่นที่มาจากอีกโลกอื่นใช่ไหม?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Người Lưu Vong đó, Antonov, trông giống như một thành viên của Delta Seven đến từ một thế giới khác, phải không?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "也许那个叫做安东的流浪者，曾是其他世界德尔塔部队的队员呢？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Diese Exilantin, Antonow, sah aus wie ein Mitglied von Delta Seven aus einer anderen Welt, nicht wahr?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Cette exilée, Antonov, on dirait bien qu'elle était membre du Delta Seven d'un autre monde, non ?"
L30_1.m_Talk_FRA = L31_1
