L34_1 = "저라면, 그런 사사로운 감정에 휘둘릴 리 없으니까요!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "私はそんな些細な感情には振り回されませんから！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Because I'm not one to be swayed by emotions!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "我不會被這種私人感情而左右！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เพราะฉันไม่ใช่คนที่จะตัดสินคนด้วยอารมณ์แวปเดียวอยู่แล้ว!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vì tôi không phải là người dễ bị cảm xúc chi phối!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "我不会被这种私人感情而左右！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich bin sowieso nicht die Art von Mensch, die sich von Emotionen beeinflussen lässt!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Parce que je ne suis pas du genre à me laisser influencer par mes émotions !"
L33_1.m_Talk_FRA = L34_1
