L42_1 = "EXILER_ACT1_INTERUDE2@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5500107
L41_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_IDLE"
L42_1 = "FX_CUTSCEN_NOISE_RUSTLE"
L41_1.m_StartFXSoundName = L42_1
L42_1 = "COMMANDER_EXILER_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "의약품이랑, 배수용 파이프…… 그리고 정수장치와 당근 모종 말씀입니까?"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "医薬品と、配水用のパイプ……そして浄水装置とニンジンの苗木ですか？"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Medicine, a drainage pipe... a water purifier and carrot seeds. Is that correct?"
L41_1.m_Talk_ENG = L42_1
L42_1 = "藥品、排水管……以及淨水裝置和胡蘿蔔苗，對嗎？"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ยารักษาโรค ท่อระบายน้ำ...เครื่องกรองน้ำ และเมล็ดแครอท มันถูกต้องมั้ย?"
L41_1.m_Talk_THA = L42_1
L42_1 = "Thuốc, ống thoát nước... máy lọc nước và hạt cà rốt. Đúng không?"
L41_1.m_Talk_VTN = L42_1
L42_1 = "药品、排水用管道……以及净水装置和胡萝卜苗，对吗？"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Medikamente, Abflussrohre ... ein Wasserreiniger und Karottensamen. Stimmt das so?"
L41_1.m_Talk_DEU = L42_1
L42_1 = "Des médicaments, un tuyau de drainage... un purificateur d'eau et des graines de carotte. C'est bien ça ?"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EXILER_ACT1_INTERUDE2@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 5500107
L42_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "UNIT_LAUGH"
L42_1.m_Face = L43_1
L43_1 = "COMMANDER_EXILER_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "알겠습니다. 다음 보급 때, 소령님께 건의해보도록 하죠."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "わかりました。次回の補給の際に少佐に取り合ってみます。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Understood. I'll suggest them to the major on my next supply run."
L42_1.m_Talk_ENG = L43_1
L43_1 = "我明白了，下次補給時，我會向少校報告的。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "อ๋อ ฉันคิดออกแล้ว  หรือว่าพวกเขาอยากให้ฉันมาแนะนำให้การดำรงชีวิตของคนยุคต่อไป "
L42_1.m_Talk_THA = L43_1
L43_1 = "Hiểu rồi. Cháu sẽ gợi ý với thiếu tá trong lần chạy tiếp tế tiếp theo."
L42_1.m_Talk_VTN = L43_1
L43_1 = "我明白了。下次补给时，我会向少校大人报告的。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Verstanden. Ich werde bei der nächsten Lieferung mal versuchen, dem Major einen Vorschlag zu unterbreiten."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Compris. Je ferai en sorte de suggérer ça au major lors du prochain réapprovisionnement."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
L44_1 = 43
L43_1.m_CutScenProcessKey = L44_1
