L45_1 = "EXILER_ACT1_INTERUDE2@44#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 44
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 5500107
L44_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L45_1 = "OLDMAN_VOICE_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "아유, 고마워요. 안토노프 행정관님이 없었으면 불편해서 어떻게 살았을지 몰라."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "まあ、ありがとうね。アントノフ行政官がいなかったら、ここはかなり不便だったろうねえ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Oh, thank you. I don't know what we'd do without you, Officer Antonov."
L44_1.m_Talk_ENG = L45_1
L45_1 = "哎呀，真是太感謝了！如果沒有安東諾夫行政官，我都不知道該怎麼活下去。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เอ่อ ขอบคุณ หนูมากนะ ตาไม่รู้ว่าเราจะทำยังไงได้ ถ้าไม่มีหนูช่วย เจ้าหน้าที่แอนโทนอฟ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Ồ, cảm ơn cô. Không biết chúng tôi sẽ làm sao nếu không có cô, Sĩ quan Antonov."
L44_1.m_Talk_VTN = L45_1
L45_1 = "哎呦，真是太感谢了！如果没有安东行政官，我都不知道该怎么活下去。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Oh, vielen Dank. Ich weiß nicht, was wir ohne Sie tun würden, Verwaltungsbeamtin Antonow."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Oh, merci. Je ne sais pas ce que nous ferions sans vous, officier Antonov."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
