L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_IDLE"
L46_1 = "COMMANDER_EXILER_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "C"
L46_1 = "아닙니다. 군인으로서 당연한 의무인걸요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "いいえ。軍人として当然の義務ですから。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "You don't have to thank me. I'm just doing my job as a soldier."
L45_1.m_Talk_ENG = L46_1
L46_1 = "不用謝，作為一名軍人，這是我應盡的義務。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ไม่เป็นไรเลยคะ หนูก็แค่ทำตามหน้าที่ในฐานะทหารเองค่ะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Không sao. Cháu chỉ đang làm việc của một người lính thôi."
L45_1.m_Talk_VTN = L46_1
L46_1 = "不用谢。作为一名军人，这是我应尽的义务。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Sie brauchen mir nicht zu danken. Ich komme lediglich meiner Pflicht als Soldatin nach."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Vous n'avez pas à me remercier. Je ne fais que mon travail en tant que soldat."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
L47_1 = "EXILER_ACT1_INTERUDE2@46#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 46
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5500107
L46_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "UNIT_LAUGH"
L46_1.m_Face = L47_1
L47_1 = "COMMANDER_EXILER_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "오히려 감사는 제가 드리고 싶군요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "むしろ私の方こそ感謝いたします。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Actually, I should be the one thanking you."
L46_1.m_Talk_ENG = L47_1
L47_1 = "反而是我應該向你表示感謝。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "จริงๆแล้วหนูสิควรจะเป็นคนที่ขอบคุณพวกคุณทุกคน"
L46_1.m_Talk_THA = L47_1
L47_1 = "Thật ra, cháu mới là người nên cảm ơn."
L46_1.m_Talk_VTN = L47_1
L47_1 = "反而是我应该向您表示感谢。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Eigentlich habe ich eher Ihnen zu danken."
L46_1.m_Talk_DEU = L47_1
L47_1 = "À vrai dire, c'est plutôt moi qui devrais vous remercier."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EXILER_ACT1_INTERUDE2@47#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 47
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 5500107
L47_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "COMMANDER_EXILER_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "인프라가 구축된 1지구 거주권을 포기하시고 굳이 최전선의 7지구를 선택하셨으니까요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "インフラが整った第1地区の居住権を諦めて、あえて最前線である第7地区を選んでくださったではないですか。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You chose to give up your residence in the well-infrastructured District 1 and move to the frontlines of District 7."
L47_1.m_Talk_ENG = L48_1
L48_1 = "你放棄了基礎設施完善的第一區居住權，堅定選擇了處於最前線的第七區。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ที่ทุกคุณยอมสละถิ่นที่อยู่ในเขต 1 ที่มีโครงสร้างพื้นฐานที่ดีอยู่แล้ว และก็ยอมย้ายมายังแนวป้องกันฐานหน้าเขต 7 แทน"
L47_1.m_Talk_THA = L48_1
L48_1 = "Mọi người đã chọn từ bỏ nơi cư trú tại Quận 1 có cơ sở hạ tầng tốt và chuyển đến tiền tuyến ở Quận 7."
L47_1.m_Talk_VTN = L48_1
L48_1 = "您放弃了基础设施完善的第1区居住权，坚定选择了处于最前线的第7区。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Schließlich haben Sie sich dafür entschieden, Ihren Wohnsitz im gut ausgebauten Distrikt 1 aufzugeben und an die Front von Distrikt 7 umzuziehen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous avez choisi de renoncer à votre résidence dans le district 1, qui était pourtant bien équipée en termes d'infrastructures, pour vous déplacer vers les premières lignes du district 7."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EXILER_ACT1_INTERUDE2@48#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 48
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5500107
L48_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_IDLE"
L49_1 = "COMMANDER_EXILER_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "혹시 뭔가 특별한 이유라도 있으신겁니까?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "何か特別な理由でもおありだったのですか？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "May I ask if there was a specific reason for doing so?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "是有什麼特別的原因嗎？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "หนูขอถามอะไรหน่อยได้ไหม ว่าทำไมถึงมาอยู่ที่นี่คะ ?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Cháu có thể hỏi liệu có một lý do nào để làm vậy không?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "是有什么特别的原因吗？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Dürfte ich fragen, ob es einen bestimmten Grund dafür gab?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Puis-je vous demander si vous aviez une raison particulière de faire ça ?"
L48_1.m_Talk_FRA = L49_1
