L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 50
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5500107
L50_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "OLDMAN_VOICE_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "그게 별 건 아니고, 사실 여기가 원래 내 고향이었거든."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "別に大した理由じゃないんだけれど、実はここが私の故郷なのよ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Oh, it's nothing special. You see, this is my hometown."
L50_1.m_Talk_ENG = L51_1
L51_1 = "呵呵，沒什麼特別的，實際上這裡才是我的家鄉。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "โอ้ย คิดมากเกินไปแล้วลูก ตาไม่มีจุดประสงค์อื่นเลย นอกจากที่นี่คือบ้านเกิดของผมก็แค่เท่านั้น"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ồ, cũng không có gì đặc biệt cả. Cô thấy đấy, đây là quê hương của tôi."
L50_1.m_Talk_VTN = L51_1
L51_1 = "呵呵，没什么特别的，实际上这里才是我的家乡。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Nun ja, ehrlich gesagt war Distrikt 7 ursprünglich meine Heimatstadt."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Oh, pas vraiment. C'est ma ville natale, vous savez."
L50_1.m_Talk_FRA = L51_1
