L4_1 = "EXILER_ACT1_INTERUDE2@53#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 53
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5500107
L3_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L4_1 = "OLDMAN_VOICE_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "저기 방위선 기지가 있던 곳에는 원래 커다란 쇼핑몰이 있었고. 저 방벽 너머에는 역이 있었지. 내가 거기서 근무했었고."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "あそこの防衛線の基地があった場所にはもともと大きなショッピングモールがあってねえ。あの防壁の向こう側には駅があって、私はそこで昔働いていたのよ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Right there, where the base is, there used to be a huge shopping mall. And over the wall, there was a station. I know because I used to work there."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我記得啊，防線基地所在的地方，原來是一座大型購物中心。那個屏障後面原先有個車站，我曾經就在那裡工作。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ใช่แล้ว ที่ฐานทัพนั้นเคยเป็นห้างสรรพสินค้าขนาดใหญ่มาก่อน และเหนือกำแพงก็มีสถานีรถไฟ ที่ตารู้ก็เพราะตาเคยทำงานที่นั่นมาก่อน"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ngay tại chỗ đó, chỗ căn cứ ấy, từng là một trung tâm mua sắm khổng lồ. Và phía trên bức tường, có một nhà ga. Tôi biết vì tôi đã từng làm việc ở đó."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我记得啊，防线基地所在的地方，原来是一座大型购物中心。那个屏障后面原先有个车站，我曾经就在那里工作。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Genau dort, wo jetzt die Basis errichtet wurde, befand sich früher ein riesiges Einkaufszentrum. Und über der Mauer befand sich eine Station. Ich habe dort früher gearbeitet."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Juste là où se trouve la base, il y avait autrefois un énorme centre commercial. Et au delà du mur, il y avait une station de train. Je le sais parce que je travaillais là-bas."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
