L7_1 = "EXILER_ACT1_INTERUDE2@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 5500107
L6_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "OLDMAN_VOICE_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "후후, 사람이라는 게 결국 자기가 태어나고 자란 땅을 기억할 수밖에 없는 것 같아."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ふふ、人は結局自分の生まれ育った土地は忘れられないのね。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Ha ha. It just goes to show that people have no choice but to remember where they were born and raised."
L6_1.m_Talk_ENG = L7_1
L7_1 = "呵呵，人啊，到最後懷念的只有自己出生長大的地方。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ไม่ใช่ทางเลิกอะไรทั้งนั้น มันก็แค่ทำให้เราได้นึกถึงที่เก่าๆ และยังคงจดจำที่ที่พวกเขาเกิดและเติบโตมาก็แค่นั้น"
L6_1.m_Talk_THA = L7_1
L7_1 = "Ha ha. Nó chỉ thể hiện là mọi người không có lựa chọn nào ngoài việc nhớ nơi mình sinh ra và lớn lên."
L6_1.m_Talk_VTN = L7_1
L7_1 = "哎，人啊，到最后怀念的只有自己出生长大的地方。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Haha. Ich glaube, dass den Menschen letztendlich keine andere Wahl bleibt, als sich an den Ort zu erinnern, an dem sie geboren wurden und aufgewachsen sind."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Hé hé. Je crois bien qu'on n'oublie jamais le lieu où l'on est né et où l'on a grandi."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EXILER_ACT1_INTERUDE2@57#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 57
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 5500107
L7_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "OLDMAN_VOICE_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "죽을 때가 다 된 건지…… 그 시절 추억이 아른아른 떠올라서……."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "お迎えが来る日が近いのか……昔の思い出を色々思い出しちゃって……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Maybe my time is coming to an end... I keep feeling nostalgic about the old days..."
L7_1.m_Talk_ENG = L8_1
L8_1 = "也許是我的時間快到了……以前的記憶總是在腦海隱隱約約地浮現……"
L7_1.m_Talk_TWN = L8_1
L8_1 = "บางทีเวลาของตาเองก็ใกล้จะหมดลงแล้ว...แต่ก็ยังคงคิดถึงวันเก่าๆอยู่เสมอ..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Có lẽ thời của tôi sắp đến lúc kết thúc... Tôi cứ hoài niệm về ngày xưa..."
L7_1.m_Talk_VTN = L8_1
L8_1 = "也许是我的时间快到了……以前的记忆总是在脑海隐隐约约地浮现……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Vielleicht neigt sich mein Leben langsam dem Ende zu ... In letzter Zeit kommen nämlich oft die Erinnerungen an die guten alten Zeiten wieder hoch ..."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Peut-être que mon heure est bientôt arrivée... Je n'arrête pas de me sentir nostalgique à propos du bon vieux temps..."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EXILER_ACT1_INTERUDE2@58#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 58
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 5500107
L8_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "OLDMAN_VOICE_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "이곳을 버리지 않고, 살 수 있게 만들어준 자네들이 나는 늘 고마워요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "ここを捨てずに、暮らせるようにしてくれたあなたたちにはいつも感謝していますよ。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "So, I'm grateful that you didn't abandon this place and made it habitable again."
L8_1.m_Talk_ENG = L9_1
L9_1 = "我一直很感謝你們，沒有放棄這個地方，讓我能在這裡生活。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ตาดีใจที่หนูไม่ทิ้งที่แห่งนี้ไปและทำให้ที่นี่น่าอยู่ขึ้นอีกครั้ง"
L8_1.m_Talk_THA = L9_1
L9_1 = "Vì vậy, tôi rất biết ơn vì cô đã không bỏ rơi nơi này và khiến nó có sức sống trở lại."
L8_1.m_Talk_VTN = L9_1
L9_1 = "我一直很感谢你们，没有放弃这个地方，让我能在这里生活。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich bin Ihnen wirklich sehr dankbar, dass Sie diesen Ort nicht aufgegeben, sondern ihn wieder bewohnbar gemacht haben."
L8_1.m_Talk_DEU = L9_1
L9_1 = "C'est pourquoi je suis reconnaissante que vous n'ayez pas abandonné cet endroit et que vous l'ayez rendu habitable à nouveau."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EXILER_ACT1_INTERUDE2@59#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 59
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 5500107
L9_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L10_1 = "OLDMAN_VOICE_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "아, 그러고 보니 안토노프 행정관님은 고향이 어디라고 했더라?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "ああ、そういえばアントノフ行政官の故郷はどこと言っていたかしら？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Oh, that's right. Where did you say your home was, Officer Antonov?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "啊，我還沒問過……安東諾夫行政官的家鄉在哪裡？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "อ๋อใช่แล้ว หนูบอกว่าบ้านของหนูอยู่ที่ไหนนะ เจ้าหน้าที่แอนโทนอฟ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Ồ, đúng rồi. Cô nói nhà cô ở đâu cơ, sĩ quan Antonov?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "啊，我还没问过……安东行政官的家乡在哪里？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ach ja, stimmt. Wo war gleich nochmal Ihr Zuhause, Verwaltungsbeamtin Antonow?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Oh, mais d'ailleurs. Où avez-vous dit que votre maison était, officier Antonov ?"
L9_1.m_Talk_FRA = L10_1
L10_1 = {}
