L14_1 = "EXILER_ACT1_INTERUDE2@63#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 63
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5500107
L13_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "OLDMAN_VOICE_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "아이고, 내 정신 좀 봐! 우리 손주 밥시간이 다 됐네."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "おお、ごめんねえ！　もうご飯の時間だったね。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Oh dear! Look at the time! It's time to feed my grandson already."
L13_1.m_Talk_ENG = L14_1
L14_1 = "呵呵，瞧我這記性！都快到孫子吃飯的時間了。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "โอ๊ะ โอ เด็กน้อยของตา! ดูสิ! ถึงเวลาต้องป้อนอาหารหลานชายแล้ว"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ôi chao! Mấy giờ rồi! Đã đến lúc cho cháu tôi ăn rồi."
L13_1.m_Talk_VTN = L14_1
L14_1 = "呵呵，瞧我这记性！都快到孙子吃饭的时间了。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Meine Güte, wie vergesslich ich doch bin! Es ist Zeit, meinen Enkel zu füttern."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Oh ! Regardez l'heure ! Il est déjà temps pour moi d'aller donner à manger à mon petit-fils."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EXILER_ACT1_INTERUDE2@64#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 64
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5500107
L14_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "OLDMAN_VOICE_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "행정관님, 기지로 돌아가기 전에 우리 집에 들러서 순무 좀 가져가요."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "行政官、基地に戻られる前に家に寄っていってくださいな、カブをお渡ししたいわ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Officer Antonov, please come over to my house for some turnips before going back to base."
L14_1.m_Talk_ENG = L15_1
L15_1 = "行政官，來我們家拿些蕪菁再走吧。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ถ้าเจ้าหน้าที่แอนโทนอฟว่าง โปรดมาที่บ้านของเรานะ เดี๋ยวตาจะเอาหัวผักกาดให้ก่อนที่จะกลับฐานนะ"
L14_1.m_Talk_THA = L15_1
L15_1 = "Sĩ quan Antonov, mời cô đến thăm nhà tôi lấy ít củ cải trước khi về căn cứ nhé."
L14_1.m_Talk_VTN = L15_1
L15_1 = "行政官，来我们家拿些萝卜再走吧。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Verwaltungsbeamtin Antonow, bitte schauen Sie mal bei mir zu Hause vorbei, bevor Sie zur Basis zurückkehren. Ich werde Ihnen ein paar Rüben mitgeben."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Officier Antonov, venez chez moi récupérer quelques navets avant de retourner à la base."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EXILER_ACT1_INTERUDE2@65#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 65
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5500107
L15_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_SURPRISE"
L16_1 = "COMMANDER_EXILER_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L15_1.m_Crash = 15
L16_1 = "아뇨! 괜찮습니다. 대가를 바라고 한 행동이 아닙니다."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "いいえ！　大丈夫です。見返りを期待してのことではありませんので。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Oh, that's okay. We don't do this to get anything in return."
L15_1.m_Talk_ENG = L16_1
L16_1 = "不用了！沒關係的，我們不是為了得到回報才這樣做的。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "โอ้วไม่เป็นไรค่ะ หนูมาช่วยไม่ได้เพื่อหวังอะไรตอบแทนเลยค่ะ"
L15_1.m_Talk_THA = L16_1
L16_1 = "Ồ, không sao ạ. Chúng cháu không làm việc để nhận lại gì đâu ạ."
L15_1.m_Talk_VTN = L16_1
L16_1 = "不用了！没关系的。我们不是为了得到回报才这样做的。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Danke, aber das passt schon. Ich erwarte keine Gegenleistung für meine Dienste."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Oh, ça ira. Nous ne faisons pas cela pour obtenir quoi que ce soit de votre part."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
