L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5500107
L17_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "OLDMAN_VOICE_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "그러지 말고. 신세를 졌으면 원래 갚아야 하는 거야."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "そう言わずに。親切にしてもらったからには、お礼をしなくちゃ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Please. It's only fair to repay the people who help you."
L17_1.m_Talk_ENG = L18_1
L18_1 = "你就別推辭了，受到你們的照顧，報答是應該的。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ได้โปรดรับไว้เถอะนะ  ถือเป็นการตอบแทนและนำใจจากเรานะ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Làm ơn đấy. Chỉ là công bằng khi trả ơn những người đã giúp đỡ mình phải không."
L17_1.m_Talk_VTN = L18_1
L18_1 = "您就别推辞了，受到了你们的照顾，报答是应该的。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Sie sind viel zu bescheiden. Wir stehen zutiefst in Ihrer Schuld, also bitte nehmen Sie zumindest ein paar Rüben als Entschädigung an."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Allons, je vous en prie. Il est normal de dédommager les gens qui vous aident."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
