L22_1.m_Crash = L23_1
L23_1 = "순무 빵, 순무 스프, 순무 샐러드, 순무 조림 심지어 순무 스테이크까지!!"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "カブのパンに、カブのスープ、カブのサラダ、カブの煮込みに、カブステーキまで！！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Turnip bread, turnip soup, turnip salad, braised turnip, and even turnip steak!!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "蕪菁麵包、蕪菁湯、蕪菁沙拉、燉蕪菁、竟然還有蕪菁排！？"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ขนมปังหัวผักกาด ซุปหัวผักกาด สลัดหัวผักกาด หัวผักกาดตุ๋น และก็ยังเป็นกระทั่งสเต็กหัวผักกาด!!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Bánh mì củ cải, súp củ cải, salad củ cải, củ cải om, và thậm chí cả bít tết củ cải!!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "萝卜面包、萝卜汤、萝卜沙拉、炖萝卜、甚至牛排里也有萝卜，我讨厌讨厌讨厌！！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Rübenbrot, Rübensuppe, Rübensalat, geschmorte Rüben und sogar Rübensteak!!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Pain de navet, soupe de navets, salade de navet, navet braisé et même steak de navet !"
L22_1.m_Talk_FRA = L23_1
