L24_1 = "이러다가 정수리에서 머리카락 대신 잎사귀가 자랄 지경이라고!"
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "このまま行けばじきに頭のてっぺんから、髪の毛じゃなくて葉っぱが生えくるわ！"
L23_1.m_Talk_JPN = L24_1
L24_1 = "At this rate, I'll be growing turnip leaves on my head instead of hair!"
L23_1.m_Talk_ENG = L24_1
L24_1 = "再這樣吃下去，我的頭上都要長蕪菁葉子了！"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ตอนนี้ ฉันหน้าของฉันจะเป็นหัวผักกาดอยู่แล้ว!"
L23_1.m_Talk_THA = L24_1
L24_1 = "Cứ thế này, tôi sẽ mọc lá củ cải trên đầu thay vì tóc mất!"
L23_1.m_Talk_VTN = L24_1
L24_1 = "再这样吃下去，我的头上都要长萝卜叶子了！"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Bei diesem Tempo werden mir bald Rübenblätter statt Haaren auf dem Kopf wachsen!"
L23_1.m_Talk_DEU = L24_1
L24_1 = "À ce rythme, je vais avoir des feuilles de navet qui vont pousser à la place des cheveux !"
