L27_1 = "사이버 캣, 이 순무는 셸터 주민분들이 직접 재배한 소중한 식량입니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "サイバーキャット、このカブはシェルターの住民の方々が栽培された大事な食糧なんですよ。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Cyber Cat, these turnips are precious rations the shelter residents farmed on their own."
L26_1.m_Talk_ENG = L27_1
L27_1 = "賽博貓，這些蕪菁是庇護中心的居民親自種植的寶貴糧食。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "นี่ เจ้าแมวไซเบอร์ หัวผักกาดพวกนี้ คืออาหารล้ำค่าที่ผู้พักอาศัยในสถานสงเคราะห์ปลูกไว้กินเองเชียวนะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Cyber Cat, những củ cải này là khẩu phần quý giá mà cư dân nơi trú ẩn tự trồng trọt."
L26_1.m_Talk_VTN = L27_1
L27_1 = "赛博猫，这些萝卜是保护所的居民们亲自栽培的宝贵粮食。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Cyber ​​Cat, diese Rüben sind wertvolle Nahrungsmittel, die die Bewohner der Notunterkünfte selbst angebaut haben."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Cyber Cat, ces navets sont des rations précieuses que les résidents du refuge ont cultivés eux-mêmes."
L26_1.m_Talk_FRA = L27_1
