L27_1.m_Crash = 10
L28_1 = "그러니까 하나도 남기지 말고 꼭꼭 씹어서 먹도록 해요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "ですから、残さずによく味わって食べてくださいね。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Make sure to eat every last bit so it doesn't go to waste."
L27_1.m_Talk_ENG = L28_1
L28_1 = "所以，一點也不能浪費。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "รีบกินให้หมด อย่ากินทิ้งขว้าง อย่าปล่อยให้เหลือทิ้งเสียของเชียวนะ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Nhớ ăn đến miếng cuối cùng kẻo lãng phí."
L27_1.m_Talk_VTN = L28_1
L28_1 = "所以，一点也不能浪费。"
L27_1.m_Talk_SCN = L28_1
