L28_1.m_Talk_THA = L29_1
L29_1 = "A! Chúng ta có một người hay càu nhàu nữa vì Thiếu tá không còn vậy nữa!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "哼！最近少校不唠叨了，又出现了个新的唠叨鬼！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Urgh! Jetzt, wo der Major endlich Ruhe gibt, ist eine neue Nörglerin aufgetaucht!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Beurk ! Je crois bien qu'on s'est trouvé une autre mégère maintenant que le major est plus là !"
