L30_1.m_CharScale = L31_1
L30_1.m_CharScaleTime = 0.01
L31_1 = "알고 있어? 난 정식 대원은 아니지만 따지고 보면, 나는 행정관인 너보다 상관이라고?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "知ってる？　アタシは正式な隊員じゃないけど、厳密にいえば行政官のアンタより上司なのよ？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Did you know this? I may not be an official member, but I do outrank you!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "你知不知道？雖然我不是正式隊員，但真要說起來，我可是你的上司！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เธอรู้หรือปล่าว? ถึงฉันไม่ใช่สมาชิกอย่างเป็นทางการ แต่ฉันก็เหนือกว่าคุณนะ รู้ไหม!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cô đã biết chưa? Tôi có thể không phải là thành viên chính thức, nhưng tôi có thứ hạng cao hơn cô!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "你知不知道？虽然我不是正式队员，但仔细算起来，我可是你的上司！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wusstest du das eigentlich? Ich bin zwar kein offizielles Mitglied, aber ich habe trotzdem einen viel höheren Rang als du!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tu sais quoi ? Je suis peut être pas un membre officiel, mais je suis ton supérieur hiérarchique !"
L30_1.m_Talk_FRA = L31_1
