L31_1.m_Talk_TWN = L32_1
L32_1 = "อีกอย่าง นี่คือการละเมิดสิทธิของเด็กและเป็นการก่อกบฏด้วยนะ ฉันขอเตือนเธอไว้ก่อน!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Nói cách khác, đây là lạm dụng trẻ em và nổi loạn, tôi cho cô biết!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "换句话说，你这算以下犯上兼虐待儿童！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Mit anderen Worten, das ist Kindesmissbrauch und Gehorsamsverweigerung!"
L31_1.m_Talk_DEU = L32_1
