L35_1.m_Talk_VTN = L36_1
L36_1 = "为了国家，孩子最重要的任务就是健康成长。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Und die wichtigste Mission eines Kindes ist es, groß und stark zu werden."
L35_1.m_Talk_DEU = L36_1
