L3_1 = "네? 말씀하신 표본과 보고서 정리를 모두 마쳐서 보고하러 왔습니다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "はい？　おっしゃっていた標本と報告書をまとめ終えたので、報告に来たのですが。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Hmm? I'm here to report back because I have completed organizing the samples and reports you handed me."
L2_1.m_Talk_ENG = L3_1
L3_1 = "嗯？我來向你報告，之前你說的樣本和報告都整理完了。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "อืมคือ? ฉันมาที่นี่เพื่อแจ้งดร.ค่ะ ฉันส่งตัวอย่างและรายงานให้คุณเรียบร้อยแล้วนะคะ"
L2_1.m_Talk_THA = L3_1
L3_1 = "Hửm? Tôi ở đây để báo cáo lại vì tôi đã sắp xếp xong các mẫu và bản báo cáo mà anh đã giao cho tôi."
L2_1.m_Talk_VTN = L3_1
L3_1 = "嗯？我来向您报告，之前您说的样本和报告都整理完了。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Hmm? Ich bin hier, um Ihnen Bericht zu erstatten, da ich die Zusammenstellung der von Ihnen erwähnten Proben und Berichte beendet habe."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Hum ? Je suis venue vous annoncer que j'ai terminé l'organisation des échantillons et des rapports que vous m'aviez remis."
L2_1.m_Talk_FRA = L3_1
