L4_1 = "LONE_EXILER_NPC_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "L"
L4_1 = "얼레? 그거 5년치 자료였는데? 그 많은 걸 벌써 다했다고?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "え？　あれはたしか5年分の資料だったはずだけど？　それをもう終わらせたって？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Huh? But that was five years' worth of data. You're already finished with it?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "蛤？那可是整整5年的資料啊？你全部都整理好了？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฮะ นี่เธอ? แต่นั่นเป็นข้อมูลมูลเมื่อ5 ปีที่แล้วนะ เธอเพิ่งทำมันเสร็จเหรอ?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Huh? Nhưng đó là dữ liệu trong vòng 5 năm. Cô đã làm xong nó rồi à?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "唉？那可是整整5年的资料啊？你全部都整理好了？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Hmm? Aber das waren doch die Daten der letzten 5 Jahre. Und du bist schon fertig damit?!"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Hein ? Mais c'était cinq ans de données. Tu as déjà fini ?"
L3_1.m_Talk_FRA = L4_1
