L4_1.m_Face = "UNIT_IDLE"
L5_1 = "COMMANDER_EXILER_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L5_1 = "사무행정은 책상 위에서의 전쟁이니까요. 작전만 잘 세우면 승리할 수 있습니다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "行政事務は机上での戦争ですからね。作戦をうまく立てれば勝利できます。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Office administration is a war that happens on desks. With the right strategy, victory is achieved."
L4_1.m_Talk_ENG = L5_1
L5_1 = "行政事務就像是書桌上的戰爭。只要制定好作戰計畫，就能贏得勝利。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ก็สำนักงานองค์การบริหารโลก มีรบบ่อยๆและให้ฉันช่วยวางแผนกลยุทธ์ ฉันก็เลยเพิ่งมีเวลาทำเสร็จค่ะ "
L4_1.m_Talk_THA = L5_1
L5_1 = "Hành chính văn phòng là cuộc chiến xảy ra trên bàn giấy. Với chiến lược đúng đắn, đã đạt được thắng lợi."
L4_1.m_Talk_VTN = L5_1
L5_1 = "办公行政就像是书桌上的战争。只要制定好作战计划，就能赢得胜利。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Die Verwaltung des Büros ist ein Krieg, der am Schreibtisch stattfindet. Wer gut plant, kann problemlos den Sieg erringen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "L'administration d'un bureau est une guerre qui se gagne à coups de stylo. C'est avec une stratégie appropriée que l'on décroche la victoire."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
