L5_1.m_fTalkTime = 0.03
L6_1 = "それより博士、その手にある果実は何ですか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "By the way, Doctor, what's that fruit in your hand?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "對了博士，你手上拿著的果實是什麼？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ว่าแต่ ที่ดร ถือที่มือนั่น คือผลไม้อะไรหรอคะ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "À, Tiến sĩ, trái cây trong tay anh là gì thế?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "对了博士，您手上拿着的果实是什么？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Übrigens, Doktor, was ist das eigentlich für eine Frucht in Ihrer Hand?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "D'ailleurs, qu'est-ce que c'est que ce fruit que vous tenez ?"
