L6_1.m_Pos = "L"
L6_1.m_Crash = 10
L7_1 = "아! 이건 이면세계에서 자라는 솔로카오라는 열매인데 이걸 식용 초콜릿으로……"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ああ！　これは裏世界に生育するソロカオという果実なんだけど、これを食用のチョコレートにして……"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Oh! This is a fruit from Counterside called Solocao, and I've made it into an edible chocolate..."
L6_1.m_Talk_ENG = L7_1
L7_1 = "啊！這是生長在異界的獨株可可，我把它做成了食用巧克力……"
L6_1.m_Talk_TWN = L7_1
L7_1 = "โอ้! นี่หรอ เป็นผลไม้จากเคาน์เตอร์ไซด์มันชื่อว่า Solocao และมันเอาไปทำช็อกโกแลตได้ด้วยนะ..."
L6_1.m_Talk_THA = L7_1
L7_1 = "Ồ! Đây là một loại trái cây từ Counterside tên là Solocao, và tôi đã chế biến nó thành một loại sô cô la ăn được..."
L6_1.m_Talk_VTN = L7_1
L7_1 = "啊！这是生长在异界的独株可可，我把它做成了食用巧克力……"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Oh! Dies ist eine Frucht von Counterside namens Solocao. Ich habe daraus eine essbare Schokolade gemacht ..."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Oh ! C'est un fruit venant du Contremonde appelé le Solocado, et je l'ai transformé en chocolat comestible..."
