L10_1 = "Were you seriously gonna tell her about your plans to destroy all couples using a C.O. made from chocolate?!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "你現在是打算告訴大家，你準備用巧克力做的侵蝕體拆散全世界情侶的計畫嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "นายบอกแผนการที่เรากำลังจะวางแผนทำลายคู่รักทั้งหมดโดยใช้ผลไม้วัตถุคอร์รัปต์มาทำช็อคโกแลตกับเธองั้นหรอ?!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Mày định nói với cô ấy về kế hoạch tiêu diệt tất cả các cặp đôi bằng sô cô la làm từ V.T.A.M. sao?!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "你现在是打算告诉大家，你准备用巧克力做的侵蚀体拆散全世界情侣的计划吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Wolltest du ihr ernsthaft von deinem Plan erzählen, alle Paare auf dieser Welt mit einem C. O. aus Schokolade zur Trennung zu bewegen?!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Tu comptais sérieusement lui parler de tes plans pour détruire tous les couples du monde en utilisant un O.C. fabriqué à partir de chocolat ?!"
L9_1.m_Talk_FRA = L10_1
