L11_1 = "다른 사람도 아닌, 이 고지식한 안토노프 양한테?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "しかもよりによって、この頭の堅いアントノフさんに！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Not just anyone, but the hardheaded Antonov?!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "還是對著死腦筋的安東諾夫？！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "นายจะบอกใครก็ได้แต่นั่นคือ แอนโทนอฟ ยัยคนฉลาดหัวใสนะนั่น?!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Không phải ai, mà lại nói đúng với Antonov cứng đầu?!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "还是对着死脑筋的安东小姐？！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Und das auch nicht irgendjemandem, sondern der hartnäckigen Antonow?!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Et puis c'est pas n'importe qui ! C'est Antonov ! L'inflexible !"
L10_1.m_Talk_FRA = L11_1
