L15_1 = "COMMANDER_EXILER_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "R"
L15_1 = "네? 침식된 토양에서 재배 가능한 식용 열매를 찾았다는 말씀입니까?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "はい？　侵食された土壌で栽培可能な食用果実を見つけられたんですか？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Huh? Do you mean to say that you found a fruit that's capable of being farmed on Corrupted soil?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "嗯？你是說發現了可以栽種在被侵蝕的土壤裡的食用果實嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ฮะ ว่าไงนะคะ? ดร จะบอกว่าพบผลไม้นี่ ที่สามารถปลูกบนดินที่โดนคอรัปต์ได้งั้นหรอคะ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Huh? Ý anh là đã tìm thấy một loại trái cây có thể trồng được trên đất bị Ăn Mòn?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "嗯？您是说发现了可栽培在被侵蚀的土壤里的食用果实吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Wie bitte? Wollen Sie damit sagen, dass Sie eine Frucht gefunden haben, die auf vererbten Boden angebaut werden kann?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Hein ? Voulez-vous dire que vous avez trouvé un fruit pouvant être cultivé sur un sol Corrompu ?"
L14_1.m_Talk_FRA = L15_1
