L15_1.m_Crash = 15
L16_1 = "그건 엄청난 연구 성과입니다!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "それはすごい研究成果ですね！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "That is an incredible research accomplishment!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "這是一項了不起的研究成果！"
L15_1.m_Talk_TWN = L16_1
L16_1 = "นั่นเป็นความสำเร็จด้านการวิจัยที่น่าเหลือเชื่อจริงๆเลยค่ะ!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đó là một thành tựu nghiên cứu không thể tin được!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "这是一项了不起的研究成果！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Das ist ja eine unglaubliche wissenschaftliche Errungenschaft!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Mais c'est une découverte incroyable !"
L15_1.m_Talk_FRA = L16_1
