L16_1.m_Face = L17_1
L17_1 = "COMMANDER_EXILER_NULL_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "R"
L16_1.m_Crash = 20
L17_1 = "이거라면 인류의 식량난을 해결할 수 있어요! 당장, 소령님께 보고드리죠!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "これなら人類の食糧難を解決できますよ！　今すぐ、少佐に報告しましょう！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "This could mean the end of humankind's food crisis! Let's report this to Major immediately!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "這樣一來，人類的糧食危機就能得到解決了！我要馬上向少校報告！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "หรือนี่อาจสัญญาณที่ดีในการแก้ปัญหาการขาดแคลนอาหารของมนุษยชาติ! แบบนี้เราต้องรีบรายงานให้สารวัตรทราบทันทีนะคะ!"
L16_1.m_Talk_THA = L17_1
L17_1 = "Điều này có thể là sự kết thúc cho cuộc khủng hoảng lương thực của loài người! Hãy báo cáo với Thiếu tá ngay lập tức!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "这样一来，人类的粮食危机就能得到解决了！我要马上向少校大人报告！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Dies könnte das Ende der Nahrungsmittelkrise der Menschheit bedeuten! Wir sollten das sofort dem Major melden!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Cela pourrait signifier la fin de la crise alimentaire de l'humanité ! Nous devons absolument en faire part au major !"
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
