L20_1 = "역시 믿고 있었습니다, 박사님. 당신은 세계 제일의 과학자예요!"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "さすがです、博士。あなたは世界一の科学者です！"
L19_1.m_Talk_JPN = L20_1
L20_1 = "I knew we could count on you, Doctor. You really are this world's best scientist!"
L19_1.m_Talk_ENG = L20_1
L20_1 = "我就知道博士你一定可以做到。你是世界上最偉大的科學家！"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฉันรู้ว่าเราไว้ใจคุณได้ ด็อกเตอร์ คุณเป็นนักวิทยาศาสตร์ที่เก่งที่สุดในโลกจริงๆ!"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tôi biết chúng tôi có thể tin tưởng vào anh mà, Tiến sĩ. Anh thực sự là nhà khoa học giỏi nhất thế giới này!"
L19_1.m_Talk_VTN = L20_1
L20_1 = "我就知道博士您一定可以做到。您是世界上最伟大的科学家！"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ich wusste, dass wir auf Sie zählen können, Doktor. Sie sind wirklich der beste Wissenschaftler auf dieser Welt!"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Je savais que nous pouvions compter sur vous, docteur. Vous êtes vraiment le meilleur scientifique de ce monde !"
L19_1.m_Talk_FRA = L20_1
