L31_1 = "COMMANDER_EXILER_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "R"
L30_1.m_Crash = 15
L31_1 = "박사님? 갑자기 왜 말이 없으시죠?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "博士？　どうしていきなり無言になったのですか？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Doctor? What's wrong? Why are you being so quiet?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "博士？你怎麼突然不說話了？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เอ๊ะ เป็นอะไรหรอค่ะด๊อกเตอร์? ฉันพูดอะไรผิดไปหรอคะ? ทำไมคุณถึงนิ่งเงียบแบบนี้?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tiến sĩ? Sao thế? Sao anh lại im lặng như vậy?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "博士？您怎么突然不说话了？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Doktor? Warum sind Sie denn plötzlich so still?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Docteur ? Qu'est-ce qui ne va pas ? Pourquoi êtes-vous silencieux tout à coup ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EXILER_ACT1_INTERUDE2@131#Talk"
