L32_1 = "UNIT_LAUGH"
L31_1.m_Face = L32_1
L32_1 = "LONE_EXILER_NPC_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "L"
L31_1.m_Crash = 10
L32_1 = "아이의 첫 학교는 사립이 좋을까요? 공립이 좋을까요?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "子どもが入学する小学校は私立と公立、どっちがいいかな？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Do you think it would be better to send our child to a private or public school?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "孩子的第一所學校是去私立好呢？還是去國立好呢？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "คุณคิดว่าควรส่งลูกของเราไปเรียนโรงเรียนเอกชนหรือโรงเรียนรัฐบาลอะไรจะดีกว่ากัน?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Em nghĩ gửi con của chúng mình đến trường tư thục hay công lập thì tốt hơn?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "孩子的第一所学校是去私立好呢？还是去国立好呢？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Denkst du, dass es besser wäre, unser Kind auf eine private oder öffentliche Schule zu schicken?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Penses-tu qu'il serait préférable d'envoyer notre enfant dans une école privée ou publique ?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
