L33_1 = "예? 박사님, 아이가 있으셨습니까?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "はい？　博士、お子さんがいらっしゃったんですか？"
L32_1.m_Talk_JPN = L33_1
L33_1 = "What? Doctor, do you have kids?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "嗯？博士，你有孩子了嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เอ๋ ว่าไงนะคะ ด๊อกเตอร์คุณมีลูกด้วยหรอคะ?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cái gì? Tiến sĩ, anh có con rồi à?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "嗯？博士，您有孩子了吗？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Wie bitte? Doktor, haben Sie etwa Kinder?"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Quoi ? Vous avez des enfants, docteur ?"
L32_1.m_Talk_FRA = L33_1
