L39_1 = "위험해. 농장에 있는 거주민들을 빨리 피난시켜야 해."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "まずい。農場にいる住民たちを早く避難させなければ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "This isn't good. The farming residents need to be evacuated this instant."
L38_1.m_Talk_ENG = L39_1
L39_1 = "糟糕，我得快點讓農場裡的居民去避難。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ไม่ได้การแล้ว ชักจะไม่ดีแล้ว ชาวเกษตรทุกคนต้องรีบอพยพด่วนแล้ว"
L38_1.m_Talk_THA = L39_1
L39_1 = "Không ổn rồi. Các cư dân đáng trồng trọt cần được sơ tán ngay lập tức."
L38_1.m_Talk_VTN = L39_1
L39_1 = "糟糕，我得快点让农场里的居民们去避难。"
L38_1.m_Talk_SCN = L39_1
