L45_1 = 0.5
L43_1[L44_1] = L45_1
L44_1 = "아, 안 돼. 몇 개월 동안 기른 소중한 작물들이……."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "そ、そんな。何か月もかけて育てた大切な作物が……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Oh, no. The crops we've been growing for months..."
L43_1.m_Talk_ENG = L44_1
L44_1 = "不，不！這是我們種了幾個月的珍貴糧食……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ไม่นะ นั่น นั้นมันผลผลิตที่เราช่วยกันปลูกมาตั้งหลายเดือน..."
L43_1.m_Talk_THA = L44_1
L44_1 = "Ôi không. Các loại cây trồng chúng tôi đã trồng suốt hàng tháng trời ..."
L43_1.m_Talk_VTN = L44_1
L44_1 = "不，不！这是我们种了几个月的珍贵粮食……"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Oh nein. Unsere kostbaren Pflanzen, die wir seit Monaten gezüchtet haben ..."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Oh non. Les plants que nous cultivons depuis des mois..."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EXILER_ACT1_INTERUDE2@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
