L46_1 = 0.5
L44_1[L45_1] = L46_1
L45_1 = "지금 작물 걱정할 때야! 빨리 도망치자고!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "今は作物の心配をしている場合じゃないだろ！　早く逃げようぜ！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "We don't have time to worry about crops! We need to run!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "現在是擔心作物的時候嗎！快跑吧！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เราไม่มีเวลามากังวลเรื่องผลผลิตนี้แล้วนะคะ! เราต้องวิ่งหนีกันแล้ว!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Không có thời gian để lo lắng về cây trồng đâu! Chúng ta phải chạy!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "现在是担心作物的时候吗！快跑吧！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Wir haben keine Zeit, uns um die Ernte Sorgen zu machen! Wir müssen so schnell wie möglich wegrennen!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Pas le temps de se soucier des cultures ! Il faut partir, vite !"
L44_1.m_Talk_FRA = L45_1
