L48_1.m_CharStrID = L49_1
L49_1 = "C_L_M_I"
L48_1.m_Pos = L49_1
L49_1 = "여러분, 곧 방위군이 도착할 겁니다!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "皆さん、もうすぐ防衛軍が到着します！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Everyone, the Defense Force will be arriving shortly!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "各位，保衛軍即將抵達這裡！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ทุกคน กองกำลังป้องกันกำลังจะมาถึงเร็วๆ นี้!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Mọi người, Lực Lượng Phòng Vệ sẽ đến ngay!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "各位，防卫军即将抵达这里！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Alle mal hergehört! Die Verteidigungsstreitkräfte werden in Kürze hier eintreffen!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Tout le monde, les Forces de défense vont arriver d'une minute à l'autre !"
L48_1.m_Talk_FRA = L49_1
