L49_1.m_Pos = "C"
L49_1.m_Crash = 20
L50_1 = "이곳 농장은 폐기합니다! 모두 셸터로 피신하세요!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "こちらの農場は放棄します！　皆さん、シェルターにご避難ください！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Abandon the farms! Everyone to the shelter!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "立刻放棄這個農場！請大家全部前往庇護中心避難！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "สละทิ้งฟาร์มพวกนี้ไปก่อน! แล้วให้ทุกคนอพยพไปที่ศูนย์พักพิงด่วนเลยค่ะ!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Bỏ các trang trại! Tất cả mau đến nơi trú ẩn!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "立刻放弃这个农场！请大家全部前往保护所避难！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Verlassen Sie Ihre Bauernhöfe und suchen Sie Schutz in den Notunterkünften!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Abandonnez les fermez et courez vous mettre à l'abri dans le refuge !"
L49_1.m_Talk_FRA = L50_1
