L3_1 = 30
L2_1.m_Crash = L3_1
L3_1 = "어르신! 피가 많이 나잖아요! 빨리 셸터로 대피해서 치료를!"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "お婆さん！　すごい出血です！　早くシェルターに避難して治療を！"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Ma'am! You're bleeding! Head to the shelter quickly and get treatment!"
L2_1.m_Talk_ENG = L3_1
L3_1 = "夫人！你流了很多血！請快去庇護中心接受治療！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "คุณตาค่ะ! คุณมีเลือดออกด้วย! รีบไปทำแผลที่ศูนย์พักพิงเร็วๆเลยค่ะ!"
L2_1.m_Talk_THA = L3_1
L3_1 = "Thưa bà! Bà đang chảy máu! Hãy nhanh đến nơi trú ẩn để được điều trị!"
L2_1.m_Talk_VTN = L3_1
L3_1 = "夫人！您流了很多血！请快去避难所接受治疗！"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Sie bluten ja! Gehen Sie schnell zur Notunterkunft und lassen Sie sich behandeln!"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Madame ! Vous saignez ! Allez vite au refuge pour vous faire soigner !"
L2_1.m_Talk_FRA = L3_1
