L5_1 = "OLDMAN_VOICE_NULL_NULL"
L4_1.m_CharStrID = L5_1
L5_1 = "나, 나는 괜찮아! 그보다 우리 손주가! 손주가!"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "わ、私は大丈夫！　それより孫が、私の孫が！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I-I'm okay! But my grandson! My grandson!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "我，我沒事！可是我孫子！孫子他！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ผม-ผมโอเค! แต่หลานชายของผมสิ! ช่วยหลานชายตาด้วยนะ !"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi không sao! Nhưng cháu tôi! Cháu nội của tôi!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "我、我没事！可我孙子！孙子他！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "E-es geht mir gut! Aber mein Enkel! Mein Enkel!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "J-Je vais bien, mais mon petit-fils ! Il...!"
L4_1.m_Talk_FRA = L5_1
