L12_1 = "GIRL_EXILER_NPC_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "으아, 어떡해!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "ああ、どうしよう！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Waah! What do we do?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "呃啊，我們現在該怎麼辦！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ว้าย กรีด! แล้วพวกเราจะทำยังไงดีล่ะ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Aaa! Chúng ta làm gì giờ?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "呃啊，我们现在该怎么办！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ahhh! Was sollen wir bloß tun?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Aah ! Qu'est-ce qu'on fait ?!"
