L13_1 = "GIRL_EXILER_NPC_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "괜히 여기까지 따라왔다가 이게 뭐야!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ついて来いっていうから来たのに、なんでこうなるの！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "So this is what I get for following you all the way out here?!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "早知道就不跟你到這裡來了！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "นี่หรอคือสิ่งที่ฉันได้ ที่ตามเธอมาทางนี่น่ะ?!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Theo cậu tới tận đây mà lại dính vào thứ này sao?!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "早知道就不跟你到这里来了！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich bin dir den ganzen Weg bis hierher gefolgt, nur um so zu enden?!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "J'aurais jamais dû te suivre jusqu'ici !"
L12_1.m_Talk_FRA = L13_1
