L14_1 = "BOY_EXILER_NPC_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "나, 나도 갑자기 침식체가 나타날 줄은 몰랐지!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ぼ、僕だって侵食体が現れるとは思わなかったんだ！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "H-hey, who knew a C.O. would appear!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "我，我也不知道侵蝕體會突然出現啊！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เฮ้ ก็ใครจะไปรู้ว่าพวกวัตถุคอร์รัปต์จะปรากฏตัวขึ้นน่ะ!"
L13_1.m_Talk_THA = L14_1
L14_1 = "N-này, ai mà biết được V.T.A.M. sẽ xuất hiện chứ!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "我、我也不知道侵蚀体会突然出现啊！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "W-woher hätte ich denn wissen sollen, dass plötzlich ein C. O. auftauchen würde?!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "H-Hé, je pouvais pas savoir qu'un O.C. allait apparaître tout à coup !"
L13_1.m_Talk_FRA = L14_1
