L17_1 = "GIRL_EXILER_NPC_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "저 문, 금방이라도 부서질 것 같아!"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "あのドア、今にも壊れそう！"
L16_1.m_Talk_JPN = L17_1
L17_1 = "The door... It's going to break open soon!"
L16_1.m_Talk_ENG = L17_1
L17_1 = "那扇門好像撐不住了！"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ประตูนั่น...มันกำลังจะพังแล้ว !"
L16_1.m_Talk_THA = L17_1
L17_1 = "Cánh cửa... Nó sẽ bị phá ra sớm thôi!"
L16_1.m_Talk_VTN = L17_1
L17_1 = "那扇门好像顶不住了！"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Das C. O. wird bald die Tür aufbrechen!"
L16_1.m_Talk_DEU = L17_1
L17_1 = "La porte... elle va pas tenir !"
L16_1.m_Talk_FRA = L17_1
