L18_1 = "EXILER_ACT1_INTERUDE2@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 167
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 5500107
L17_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "BOY_EXILER_NPC_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "괜찮아! 군인 아저씨들이 우릴 구하러 와줄 거야! 그때까지만 버티면 돼!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "大丈夫！　きっと軍人のおじさんたちが助けに来てくれる！　それまで持ちこたえよう！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "It's all right! The soldiers will come to save us! We just need to hold it together until then!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "沒事的！軍人叔叔會來救我們的！我們只要堅持到那個時候就行！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ไม่เป็นไรนะ! เดี๋ยวก็มีทหารมาช่วยพวกเรา! พวกเราก็แค่ช่วยกันดันประตูเอาไว้ก่อน จนกว่าพวกเขาจะมาช่วยเรา !"
L17_1.m_Talk_THA = L18_1
L18_1 = "Không sao đâu! Những người lính sẽ đến để cứu chúng ta! Chúng ta chỉ cần cố chờ cho đến lúc đó!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "没事的！军人叔叔们会来救我们的！我们只要坚持到那个时候就行！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Keine Sorge! Die Soldaten werden kommen, um uns zu retten! Wir müssen nur bis dahin durchhalten!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "T'inquiète ! Les soldats vont venir nous sauver ! On a juste besoin de tenir jusque là !"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
