L19_1 = "B-but how do we do that?!"
L18_1.m_Talk_ENG = L19_1
L19_1 = "是要怎麼堅持啊！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ต-แต่เราจะทำยังไงกันดีล่ะ!"
L18_1.m_Talk_THA = L19_1
L19_1 = "N-nhưng làm thế nào để chúng ta làm điều đó?!"
L18_1.m_Talk_VTN = L19_1
L19_1 = "所、所以要怎么坚持啊！"
L18_1.m_Talk_SCN = L19_1
L19_1 = "A-aber wie sollen wir das schaffen?!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "M-Mais comment on va faire ?!"
