L36_1.m_CharStrID = L37_1
L37_1 = "행정관 누나한테서 떨어져! 이 괴물!"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "お姉さんから離れて！　この化け物！"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Get away from Officer Antonov, you monster!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "離行政官姊姊遠一點！你這個怪物！"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ไปให้พ้นจากเจ้าหน้าที่แอนโทนอฟเรานะ เจ้าสัตว์ประหลาดบ้า!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Tránh xa sĩ quan Antonov ra, đồ quái vật!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "离行政官姐姐远一点！你这个怪物！"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Lass sofort Verwaltungsbeamtin Antonow los, du Monster!"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Éloignez-vous de l'officier Antonov, bande de monstres !"
