L37_1.m_Talk_JPN = L38_1
L38_1 = "W-what?! What do you think you're doing?! Get back here!"
L37_1.m_Talk_ENG = L38_1
L38_1 = "不行！？別過去！快回來！"
L37_1.m_Talk_TWN = L38_1
L38_1 = "อะ-อะไรนั่น! นี่เจ้าหนูรู้ตัวไหมว่ากำลังทำอะไรอยู่! รีบกลับมาที่นี่เดี๋ยวนี่เลย!"
L37_1.m_Talk_THA = L38_1
L38_1 = "C-cái gì?! Nhóc nghĩ nhóc đang làm gì vậy?! Quay lại đây!"
L37_1.m_Talk_VTN = L38_1
L38_1 = "不行！？别过去！退回来！"
L37_1.m_Talk_SCN = L38_1
L38_1 = "W-was?! Ihr dürft mir doch nicht nachlaufen! Tretet zurück!"
L37_1.m_Talk_DEU = L38_1
L38_1 = "Q-Quoi ?! Qu'est ce que tu crois faire ?! Reviens ici tout de suite !"
