L44_1.m_Face = "UNIT_SURPRISE"
L44_1.m_CharStrID = "JOOSHIYOON_FENRIR_AP_NULL"
L44_1.m_Pos = "L"
L45_1 = "침식체가 달려드는데 겁도 없이 뛰어들다니, 보기보다 무모하시네요. 안토노프 행정관?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "襲ってくる侵食体に飛び込むなんて、案外無茶をするんですね。アントノフ行政官？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Running straight toward a C.O.? You're more reckless than I thought, Antonov."
L44_1.m_Talk_ENG = L45_1
L45_1 = "面對排山倒海而來的侵蝕體，毫不畏懼地迎上去。你可比看起來要衝動呢，安東諾夫行政官？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "นี่พวกเธอวิ่งเข้าหาวัตถุคอร์รัปต์หรอ? พวกเธอนี่บ้าบิ่นมากกว่าที่ฉันคิดซะอีก แอนโทนอฟ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Chạy thẳng về phía một V.T.A.M.? Cô liều lĩnh hơn tôi tưởng đấy, Antonov."
L44_1.m_Talk_VTN = L45_1
L45_1 = "面对扑面而来的侵蚀体，毫不畏惧地迎上去。你可比看起来要冲动呢，安东行政官？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Sie sind direkt auf ein C. O. zugerannt? Sie sind viel rücksichtsloser als ich dachte, Verwaltungsbeamtin Antonow."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Courir tout droit sur un O.C. sans même flancher... Vous êtes plus téméraire que je ne le pensais, Antonov."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EXILER_ACT1_INTERUDE2@195#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 195
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 5500107
L45_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_Face = "UNIT_DESPAIR"
L46_1 = "COMMANDER_EXILER_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "R"
L46_1 = "별 볼일 없긴 하지만…… 일단은 카운터이긴 하니까요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "こんな私ですが……一応はカウンターですからね。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "I am still a Counter... Albeit not that strong."
L45_1.m_Talk_ENG = L46_1
L46_1 = "沒什麼大不了的……畢竟我是制裁者。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ฉันก็เป็นเคาน์เตอร์เหมือนกัน... ถึงจะไม่แข็งแกร่งขนาดนั้นก็เถอะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Tôi vẫn là một Counter... Mặc dù không mạnh lắm."
L45_1.m_Talk_VTN = L46_1
L46_1 = "没什么大不了的……毕竟我是制裁者。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Ich bin schließlich ein Counter ... wenn auch kein sonderlich starker."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Je suis toujours un Counter... même si je n'ai rien de spécial."
L45_1.m_Talk_FRA = L46_1
L46_1 = {}
