L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "R"
L46_1.m_Crash = 20
L47_1 = "아이가 죽는 것보다는 훨씬 낫겠죠."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "子どもを死なせるよりは遥かにマシです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "It was better than to let the children die."
L46_1.m_Talk_ENG = L47_1
L47_1 = "總不能看著孩子受傷吧。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ก็ยังดีกว่าปล่อยให้เด็กๆเป็นอะไรไปนะ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Còn tốt hơn là để bọn trẻ chết."
L46_1.m_Talk_VTN = L47_1
L47_1 = "总不能看着孩子受伤吧。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Es war eine bessere Option als die Kinder einfach sterben zu lassen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Et puis je ne pouvais pas laisser les enfants mourir."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
