L49_1 = "EXILER_ACT1_INTERUDE2@198#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 198
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5500107
L48_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "BOY_EXILER_NPC_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "미, 미안해, 행정관 누나……."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ご、ごめん、行政官のお姉さん……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I-I'm sorry, Officer Antonov..."
L48_1.m_Talk_ENG = L49_1
L49_1 = "對，對不起。行政官姊姊……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ผ-ผมขอโทษ เจ้าหน้าที่แอนโทนอฟ..."
L48_1.m_Talk_THA = L49_1
L49_1 = "Em xin lỗi, sĩ quan Antonov..."
L48_1.m_Talk_VTN = L49_1
L49_1 = "对、对不起。行政官姐姐……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "E-Entschuldigung, Verwaltungsbeamtin Antonow ..."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Je-je suis désolé, officier Antonov..."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EXILER_ACT1_INTERUDE2@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 5500107
L49_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "UNIT_LAUGH"
L49_1.m_Face = L50_1
L49_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L50_1 = "COMMANDER_EXILER_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "C_F_R"
L49_1.m_Pos = L50_1
L50_1 = "아닙니다. 오히려 절 지켜주려고 하셨잖아요, 작은 기사님?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "いいえ。むしろ私を守ろうとしてくれたでしょう、小さな騎士さん？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "No need for an apology. You were just trying to save me, weren't you, Little Knight?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "不用道歉。你是想保護我，對嗎，小騎士？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ไม่เป็นไร เธอก็แค่อยากช่วยฉันใช่ไหม เจ้าหนูอัศวินน้อย?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Không cần xin lỗi. Nhóc chỉ đang cố cứu chị thôi, phải không, chàng hiệp sĩ bé?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "不用道歉。你是想保护我，对吗，小骑士？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Schon gut. Du hast schließlich nur versucht, mich zu retten, nicht wahr, mein kleiner Ritter?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Pas besoin de t'excuser. Tu essayais juste de me sauver la vie, n'est-ce pas, petit chevalier ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EXILER_ACT1_INTERUDE2@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 5500107
L50_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "COMMANDER_EXILER_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "자, 이제 다들 셸터로 돌아가요. 모두 기다리고 있으니까."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "さあ、もうシェルターにお戻りください。皆さんが待っていますから。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Now, get back to the shelter. Everyone is waiting for you."
L50_1.m_Talk_ENG = L51_1
L51_1 = "好了，我們現在回庇護中心吧。大家都在等著我們呢。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "เอาหละตอนนี้พวกเรากลับที่พักกันเถอะ ทุกคนกำลังรอพวกเธออยู่"
L50_1.m_Talk_THA = L51_1
L51_1 = "Giờ thì trở lại nơi trú ẩn đi. Mọi người đang chờ đợi mấy đứa."
L50_1.m_Talk_VTN = L51_1
L51_1 = "好了，我们现在回庇护所吧。大家都在等着我们呢。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Geht jetzt schnell zurück zu den Notunterkünften. Es warten bestimmt schon alle auf euch zwei."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Maintenant, retournez au refuge, tous les deux. Tout le monde vous attend."
L50_1.m_Talk_FRA = L51_1
