L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "……이상으로 금일, 제7지구의 행정 보고를 마치겠습니다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "……以上で本日の第7地区に関する行政報告を終わります。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "...That will be all for today's District 7 briefing."
L5_1.m_Talk_ENG = L6_1
L6_1 = "……以上，就是今天的第七區的行政報告。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "...นั่นคือรายงานสรุปทั้งหมดของเขต 7 ของวันนี้ "
L5_1.m_Talk_THA = L6_1
L6_1 = "…Nội dung họp giao ban Quận 7 hôm nay đến đây là hết."
L5_1.m_Talk_VTN = L6_1
L6_1 = "……以上，就是今天的第7区行政报告。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "... Damit erkläre ich meine heutige Berichterstattung von Distrikt 7 für beendet."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Ce sera tout pour le briefing du district 7 d'aujourd'hui..."
L5_1.m_Talk_FRA = L6_1
