L10_1 = "COMMANDER_EXILER_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "R"
L10_1 = "카린 웡 소령님? 무슨 생각 하십니까?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "カリン・ウォン少佐？　何かお悩みでも？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Major Karin Wong, what are you thinking about?"
L9_1.m_Talk_ENG = L10_1
L10_1 = "卡琳少校？你在想什麼？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "สารวัตรคาริน หว่อง คุณกำลังคิดอะไรอยู่หรือปล่าวคะ?"
L9_1.m_Talk_THA = L10_1
L10_1 = "Thiếu tá Karin Wong, cô đang nghĩ gì vậy?"
L9_1.m_Talk_VTN = L10_1
L10_1 = "卡琳少校？您在想什么？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Major Karin Wong, worüber denken Sie nach?"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Major Karin Wong, à quoi pensez-vous ?"
L9_1.m_Talk_FRA = L10_1
