L11_1 = "EXILER_ACT1_INTERUDE2@210#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 210
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 5500107
L10_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_SURPRISE"
L10_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L10_1.m_Pos = "L"
L10_1.m_Crash = 20
L11_1 = "아, 아무것도 아니에요!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "い、いいえ、何でもありません！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "N-nothing!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "啊，沒什麼！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ปะ-ปล่าวไม่มีอะไร!"
L10_1.m_Talk_THA = L11_1
L11_1 = "K-không có gì!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "啊，没什么！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Oh, n-nichts!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "À-À rien !"
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EXILER_ACT1_INTERUDE2@211#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 5500107
L11_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Face = "UNIT_DESPAIR"
L11_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L11_1.m_Pos = "L"
L11_1.m_Crash = 20
L12_1 = "그보다 부상은 좀 어떠신가요? 많이 다치셨나요?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "それよりお怪我の方は大丈夫ですか？　酷くはありませんでしたか？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "But how about you? I heard you've been injured."
L11_1.m_Talk_ENG = L12_1
L12_1 = "對了，你的傷怎麼樣？傷得嚴重嗎?"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ว่าแต่เธอล่ะ? ฉันได้ยินว่าเธอเองก็บาดเจ็บนิ"
L11_1.m_Talk_THA = L12_1
L12_1 = "Nhưng còn cô thì sao? Tôi nghe nói cô đã bị thương."
L11_1.m_Talk_VTN = L12_1
L12_1 = "对了，你的伤怎么样？伤的严重吗?"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Aber was ist mit Ihnen? Ich habe gehört, dass Sie verletzt wurden."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Mais et vous ? J'ai entendu dire que vous aviez été blessée."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EXILER_ACT1_INTERUDE2@212#Talk"
