L14_1 = "UNIT_HATE"
L13_1.m_Face = L14_1
L14_1 = "COMMANDER_EXILER_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "R"
L13_1.m_Crash = 15
L14_1 = "하지만 방위선 거주민들의 사기가 걱정되는군요."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "でも防衛線近辺の住民たちの士気が気がかりです。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "But I'm worried about the residents living on the borders."
L13_1.m_Talk_ENG = L14_1
L14_1 = "但我有些擔心防線居民的士氣。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "แต่ฉันเป็นห่วงชาวบ้านที่อาศัยอยู่ตามเขตชายแดนค่ะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhưng tôi lo lắng về những cư dân sống ở biên giới."
L13_1.m_Talk_VTN = L14_1
L14_1 = "但我有些担心防线居民们的士气。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Aber ich mache mir Sorgen um die Bewohner, die an den Verteidigungslinien leben."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mais je m'inquiète pour les résidents vivant aux frontières."
L13_1.m_Talk_FRA = L14_1
