L14_1.m_Face = "UNIT_DESPAIR"
L15_1 = "COMMANDER_EXILER_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "R"
L14_1.m_Crash = 15
L15_1 = "이제 막 토지 정화 작업이 끝나고, 순무 외에 다른 식량을 재배할 수 있게 되었는데……."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "土地の浄化作業を終えて、やっとカブ以外の食糧を栽培できるようになったところだったのに……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "We just finished purifying the soil so we could plant and harvest crops other than turnips..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "好不容易才結束了土地淨化工作，可以種植蕪菁以外的糧食了……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "พวกเราเพิ่งปรับดินให้บริสุทธิ์สำหรับการปลูกผักผลไม้และจะเก็บเกี่ยวผลผลิตอื่นที่ไม่ใช่หัวผักกาดกันแล้ว..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Chúng tôi vừa xong việc thanh lọc đất để có thể trồng và thu hoạch các loại cây trồng khác ngoài củ cải..."
L14_1.m_Talk_VTN = L15_1
L15_1 = "好不容易才结束了土地净化工作，除萝卜以外，可以种植其他粮食了……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Wir hatten gerade die Reinigung des Bodens abgeschlossen, damit wir endlich andere Pflanzen als Rüben anbauen und ernten können ..."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Nous venions de terminer la purification du sol afin de pouvoir planter et récolter des cultures autres que des navets, mais..."
L14_1.m_Talk_FRA = L15_1
