L17_1 = "아니요. 쓰러진 건 다시 세우면 됩니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "いいえ。倒れたものは立て直せばいいんです。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "No problem. We can rebuild it if it falls."
L16_1.m_Talk_ENG = L17_1
L17_1 = "不。就算是跌倒了，重新站起來就好了。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "นั่นไม่ใช่ปัญหาใหญ่ เราสร้างมันขึ้นมาใหม่ได้ "
L16_1.m_Talk_THA = L17_1
L17_1 = "Không sao, chúng ta có thể xây dựng lại nếu nó sụp."
L16_1.m_Talk_VTN = L17_1
L17_1 = "不。就算是跌倒了，重新站起来就好了。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Kein Problem. Wir können sie wieder aufbauen, wenn sie fällt."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Nous pouvons toujours reconstruire ce qui a été détruit."
L16_1.m_Talk_FRA = L17_1
