L17_1.m_CharScale = L18_1
L17_1.m_CharScaleTime = 0.01
L18_1 = "불과 1년 전에 이 방위선을 되찾았을 땐, 이 땅도 침식으로 불모지 같았죠."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "つい1年前、この防衛線を取り戻した時は、この地も侵食のせいで不毛の地に思えました。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Just a year ago, when we first reclaimed the Defense Line, the soil was barren from Corruption."
L17_1.m_Talk_ENG = L18_1
L18_1 = "1年前，我們剛奪回這個防線的時候，這裡還是被侵蝕的不毛之地。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "มันแค่หนึ่งปีที่ผ่านมา หลังจากที่เรายึดแนวป้องกันกลับคืนมาในครั้งแรก ที่ดินก็แห้งแล้งเพราะการคอรัปต์"
L17_1.m_Talk_THA = L18_1
L18_1 = "Chỉ một năm trước, khi chúng tôi lần đầu tiên giành lại Phòng Tuyến, đất cằn cỗi vì sự Ăn Mòn."
L17_1.m_Talk_VTN = L18_1
L18_1 = "1年前，我们刚夺回这个防线的时候，这里还是被侵蚀的不毛之地。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Noch vor einem Jahr, als wir die Verteidigungslinie zum ersten Mal zurückeroberten, war der Boden wegen der Verderbnis unfruchtbar."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Il y a à peine un an, lorsque nous avons récupéré la ligne de défense pour la première fois, le sol était stérile à cause de la Corruption."
L17_1.m_Talk_FRA = L18_1
