L19_1 = "하지만 지금은 이렇게 어찌어찌 사람이 살 수 있는 땅이 되었습니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "しかし今は、こうしてなんとか人が住める土地になりましたよね。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "But now, it has become habitable land."
L18_1.m_Talk_ENG = L19_1
L19_1 = "但現在這裡地也成了可以居住的地方。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "แต่ตอนนี้กลายเป็นที่ดินสมบูรณ์ขึ้น"
L18_1.m_Talk_THA = L19_1
L19_1 = "Nhưng bây giờ, nó đã trở thành vùng đất có thể ở được."
L18_1.m_Talk_VTN = L19_1
L19_1 = "但现在这里地也成了可以居住的地方。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Aber jetzt ist es bewohnbares Land geworden."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Mais regardez maintenant, c'est devenu une terre habitable."
L18_1.m_Talk_FRA = L19_1
