L22_1 = "COMMANDER_EXILER_NULL_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "R"
L22_1 = "그렇군요. 제가 경솔했군요."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そうですか。私の考えが浅かったようです。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You're right. I was being rash."
L21_1.m_Talk_ENG = L22_1
L22_1 = "明白。是我太著急了。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "คุณพูดถูก ฉันไม่ความคิดมากเกินไป เราสามารถสร้างมันใหม่ได้"
L21_1.m_Talk_THA = L22_1
L22_1 = "Cô nói đúng. Tôi đã hơi vội."
L21_1.m_Talk_VTN = L22_1
L22_1 = "明白。是我太着急了。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Sie haben recht. Ich war zu voreilig."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Vous avez raison. Je crois que je m'inquiète pour rien."
L21_1.m_Talk_FRA = L22_1
