L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "R"
L23_1 = "다시 해보죠. 모두 힘을 합하면 할 수 있을 겁니다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "やり直します。全員で力を合わせればやれるはずです。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "We can try again. With everyone's help, we'll be able to restore it."
L22_1.m_Talk_ENG = L23_1
L23_1 = "我們重新來過。只要大家齊心協力，一定能做到。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เดี๋ยวเราจะกันลองอีกครั้ง เราจะต้องฟื้นฟูมันกลับมาได้อีกครั้ง"
L22_1.m_Talk_THA = L23_1
L23_1 = "Chúng ta có thể thử lại. Với sự giúp đỡ của mọi người, chúng ta sẽ có thể khôi phục nó."
L22_1.m_Talk_VTN = L23_1
L23_1 = "我们重新来过。只要大家齐心协力，一定能做到。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Wir können es einfach noch einmal versuchen. Wenn wir alle zusammenarbeiten, können wir es schaffen."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Nous pouvons réessayer. Nous y arriverons, avec l'aide de tout le monde."
L22_1.m_Talk_FRA = L23_1
