L27_1 = "EXILER_ACT1_INTERUDE2@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 5500107
L26_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L26_1.m_Pos = "C"
L27_1 = "애초에 당신이 이곳의 행정을 맡아주지 않았다면, 이렇게 빨리 방위선을 회복할 수 없었을 거예요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "そもそもあなたがここの行政官じゃなかったら、防衛線をここまで早く回復させることはできませんでした。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "If you hadn't taken charge of this place, we wouldn't have been able to recover the Defense Line this fast."
L26_1.m_Talk_ENG = L27_1
L27_1 = "當初要不是由你負責這裡的行政事務，也不會這麼快就把防線重建起來。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "หากไม่ได้เธอดูแลพื้นที่นี้ เราคงไม่สามารถฟื้นฟูแนวป้องกันได้เร็วขนาดนี้"
L26_1.m_Talk_THA = L27_1
L27_1 = "Nếu cô không phụ trách nơi này, chúng ta đã không thể khôi phục Phòng Tuyến nhanh như vậy."
L26_1.m_Talk_VTN = L27_1
L27_1 = "当初要不是由你负责这里的行政，也不会这么快就把防线重建起来。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wenn Sie nicht die Verwaltung über diesen Ort übernommen hätten, hätten wir die Verteidigungslinie nicht so schnell wiederherstellen können."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Si vous n'aviez pas pris en charge cet endroit, nous n'aurions pas pu récupérer la ligne de défense aussi rapidement."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EXILER_ACT1_INTERUDE2@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5500107
L27_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "UNIT_LAUGH"
L27_1.m_Face = L28_1
L27_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L27_1.m_Pos = "C"
L28_1 = "인정하죠. 당신은 무척 유능한 사람입니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "認めましょう。あなたは非常に優秀です。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I'll admit it. You are exceptionally competent."
L27_1.m_Talk_ENG = L28_1
L28_1 = "你是一個非常有能力的人。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ฉันยอมรับในความสามารถของเธอจริงๆ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Tôi sẽ thừa nhận. Cô có năng lực đặc biệt."
L27_1.m_Talk_VTN = L28_1
L28_1 = "你是一个非常有能力的人。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ich muss schon zugeben, Sie sind wirklich äußerst kompetent."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Je l'admets. Vous êtes une personne des plus compétentes."
L27_1.m_Talk_FRA = L28_1
