L31_1 = "EXILER_ACT1_INTERUDE2@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5500107
L30_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_SURPRISE"
L31_1 = "COMMANDER_EXILER_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "R"
L31_1 = "무슨 말씀이시죠? 이건 방위선 모든 주민이 노력하여 이루어 낸 성과입니다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "何をおっしゃるんですか？　これは防衛線の住民の方々全員の努力によるものです。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "What do you mean? These accomplishments were made by all of the residents in this area."
L30_1.m_Talk_ENG = L31_1
L31_1 = "別這麼說？防線得以重建是所有居民一起努力的結果。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ไม่หรอกค่ะทั้งหมดนี้เกิดขึ้นเพราะผู้ที่อยู่อาศัยในพื้นที่ช่วยกันตางหากล่ะ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ý cô là sao? Những thành tựu này là do tất cả các cư dân trong khu vực này đã tạo nên."
L30_1.m_Talk_VTN = L31_1
L31_1 = "您这是什么意思？防线得以重建是所有居民一起努力的结果。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Wovon reden Sie? Diese Leistung konnte nur durch die Bemühungen aller Bewohner der Verteidigungslinie erreicht werden."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Que voulez-vous dire ? C'est grâce aux efforts de tous les habitants que nous avons récupéré la ligne de défense."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EXILER_ACT1_INTERUDE2@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5500107
L31_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_IDLE"
L32_1 = "COMMANDER_EXILER_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "R"
L32_1 = "애초에 기억도, 갈 곳도 없는 처지인 저를 군에 받아주신 분은 소령님이지 않습니까?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "そもそも、記憶も行く当てもない私を軍に受け入れてくださったのは少佐ではありませんか？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "And it was you who gave me a spot in the army–someone with no recollection of herself or a place to go."
L31_1.m_Talk_ENG = L32_1
L32_1 = "當初是少校收留沒有記憶、無處可去的我的，不是嗎？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เพราะคุณที่ให้โอกาสฉันได้ทำงานในที่นั่น คนที่ไม่มีความทรงจำเกี่ยวกับตัวเองและไม่รู้ที่มาของตัวเองอย่างฉัน แค่นี้ก็เป็นพระคุณแล้วค่ะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Và chính cô là người đã cho tôi một vị trí trong quân đội - một người không có hồi ức về bản thân và không còn nơi nào để đi."
L31_1.m_Talk_VTN = L32_1
L32_1 = "当初是少校收留没有记忆、无处可去的我的，不是吗？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Und Sie waren doch diejenige, die mich überhaupt erst ins Militär aufgenommen hat, obwohl ich weder ein Gedächtnis noch einen Ort zum Bleiben hatte."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Et c'est vous qui m'avez donné une place dans l'armée, alors que j'avais perdu tous mes souvenirs et que je n'avais nulle part où aller."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
