L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L33_1.m_Pos = "L"
L34_1 = "여전히 그 로스트 쉽이나 스스로의 과거에 대한 건 떠오르지 않나요?"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "相変わらずあのロストシップや自分の過去について、何も思い出せませんか？"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Do you still not remember anything about the Lost Ship or your past?"
L33_1.m_Talk_ENG = L34_1
L34_1 = "關於那艘失落艦船和你的過去，你還是什麼都想不起來嗎？"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เธอจำอะไรเกี่ยวกับยานที่หายสาบสูญได้บ้างไหม หรืออดีตของเธอนึกอะไรได้อีกไหมคะ?"
L33_1.m_Talk_THA = L34_1
L34_1 = "Cô vẫn không nhớ bất cứ điều gì về Tàu Thất Lạc hay quá khứ của mình?"
L33_1.m_Talk_VTN = L34_1
L34_1 = "关于那艘失落舰船和你的过去，你还是什么都想不起来吗？"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Erinnern Sie sich immer noch an nichts aus Ihrer Vergangenheit oder an etwas in Bezug auf das Verlorene Schiff?"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Vous ne vous souvenez toujours de rien quant au vaisseau perdu ou à votre passé ?"
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
