L35_1 = "면목없습니다만, 그렇습니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "はい、面目ありません。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Sorry, but I'm afraid not."
L34_1.m_Talk_ENG = L35_1
L35_1 = "很抱歉，是的。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ขอโทษด้วยคะ  ฉันเกรงว่าจะไม่มีเลย"
L34_1.m_Talk_THA = L35_1
L35_1 = "Xin lỗi, nhưng tôi e là không."
L34_1.m_Talk_VTN = L35_1
L35_1 = "很抱歉，是的。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Nein, leider nicht. Tut mir sehr leid."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Navrée, mais j'ai bien peur que non."
L34_1.m_Talk_FRA = L35_1
