L35_1.m_Face = "UNIT_IDLE"
L35_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L35_1.m_Pos = "L"
L36_1 = "아니요, 당신이 사과할 문제는 아닙니다. 오히려 사과할 사람은 저니까요."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "いいえ、あなたが謝ることではありません。むしろ謝るべきなのは私の方です。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "No, it's not something you should apologize for. I should be the one apologizing."
L35_1.m_Talk_ENG = L36_1
L36_1 = "不，你不用道歉。要道歉的人應該是我。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ไม่ ไม่ ต้องขอโทษหรอก ฉันเองสิต้องขอโทษเธอ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Không, không phải xin lỗi. Tôi nên là người xin lỗi."
L35_1.m_Talk_VTN = L36_1
L36_1 = "不，你不用道歉。要道歉的人应该是我。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Nein, dafür brauchen Sie sich nun wirklich nicht zu entschuldigen. Vielmehr bin ich diejenige, die sich bei Ihnen entschuldigen sollte."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Non, ce n'est pas quelque chose dont vous devriez vous excuser. C'est moi qui vous dois des excuses."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
