L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 236
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5500107
L36_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
