L39_1[2] = L41_1
L38_1.m_CharScale = L39_1
L38_1.m_CharScaleTime = 0.01
L39_1 = "그동안 당신의 행동을 보고 줄곧 고민해왔는데, 이제 사실을 말씀드릴 때가 된 것 같군요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "あなたの行動を見ながらずっと悩んできましたが、もう真実をお話しする時だろうと思います。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I've been watching and thinking about your actions all this time, and I think it's time I told you the truth."
L38_1.m_Talk_ENG = L39_1
L39_1 = "這段期間我一直在觀察和思考你的所作所為，或許，現在是該告訴你實情了。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ฉันเฝ้าดูเธอและวิเคราะห์กระทำของเธอมาตลอด ถึงเวลาแล้วที่ฉันต้องบอกความจริงกับเธอ "
L38_1.m_Talk_THA = L39_1
L39_1 = "Tôi đã quan sát và suy nghĩ về hành động của cô suốt thời gian qua, và đã đến lúc tôi nói cho cô biết sự thật."
L38_1.m_Talk_VTN = L39_1
L39_1 = "这段期间我一直在观察和思考你的所作所为，或许，现在是该告诉你实情了。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Ich habe die ganze Zeit über Ihre Handlungen beobachtet und darüber nachgedacht, und ich denke, es ist an der Zeit, Ihnen die Wahrheit zu sagen."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Je vous ai bien observée pendant tout ce temps et j'ai beaucoup réfléchi. C'est pourquoi je pense qu'il est temps que je vous dise la vérité."
L38_1.m_Talk_FRA = L39_1
