L39_1.m_CharScale = L40_1
L39_1.m_CharScaleTime = 0.01
L40_1 = "안토노프 행정관, 당신은 사실…… 이 세계의 사람이 아닙니다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "アントノフ行政官、実はあなたは……この世界の人間ではありません。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Officer Antonov, you are... not from this world."
L39_1.m_Talk_ENG = L40_1
L40_1 = "安東諾夫行政官，其實你……不是這個世界的人。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เจ้าหน้าที่แอนโทนอฟ ที่จริงแล้วเธอ... ไม่ใช่คนจากโลกเรา"
L39_1.m_Talk_THA = L40_1
L40_1 = "Sĩ quan Antonov, cô... không phải người thế giới này."
L39_1.m_Talk_VTN = L40_1
L40_1 = "安东行政官，其实你……不是这个世界的人。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Verwaltungsbeamtin Antonow, Sie sind ... nicht aus dieser Welt."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Officier Antonov, vous n'êtes pas de ce monde."
L39_1.m_Talk_FRA = L40_1
