L43_1.m_CharScale = L44_1
L43_1.m_CharScaleTime = 0.01
L44_1 = "……그래서 저희는 당신이 기억을 되찾을 때까지 이곳에 머물게 했던 겁니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "……だからこそ、あなたが記憶を取り戻すまではここに留まるようにしました。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "...That is why we had you stay until you retrieved your memories."
L43_1.m_Talk_ENG = L44_1
L44_1 = "……所以我們才想把你留在這裡，直到你恢復記憶為止。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "...นั่นคือเหตุผลว่าทำไมพวกเราจึงให้เธออยู่ที่นี่ และรอจนกว่าความทรงจำของเธอจะกลับคืนมา"
L43_1.m_Talk_THA = L44_1
L44_1 = "...Đó là lý do tại sao chúng tôi để cô ở lại cho đến khi lấy lại được ký ức của mình."
L43_1.m_Talk_VTN = L44_1
L44_1 = "……所以我们才想把你留在这里，直到你恢复记忆为止。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "... Deshalb haben wir Sie hier bleiben lassen, bis Sie Ihre Erinnerungen zurückgewonnen haben."
L43_1.m_Talk_DEU = L44_1
L44_1 = "C'est pourquoi nous vous avons fait rester ici jusqu'à ce que vous récupériez vos souvenirs..."
L43_1.m_Talk_FRA = L44_1
