L47_1 = "EXILER_ACT1_INTERUDE2@246#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 246
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 5500107
L46_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L46_1.m_bWaitClick = true
