L46_1.m_Face = "UNIT_IDLE"
L46_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L46_1.m_Pos = "L"
L47_1 = "아니, 엄밀히 말하면 그동안 당신을 속이고 있었던 거죠."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "いいえ、厳密にいえば、ずっとあなたを騙していたんです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "No, strictly speaking, we have been deceiving you."
L46_1.m_Talk_ENG = L47_1
L47_1 = "不，嚴格來說這段時間是我欺騙了你。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "พูดง่ายๆ คือ พวกเรากำลังปิดบังความจริงเธออยู่"
L46_1.m_Talk_THA = L47_1
L47_1 = "Không, nói đúng ra, chúng tôi đã lừa dối cô."
L46_1.m_Talk_VTN = L47_1
L47_1 = "不，严格来说这段时间是我欺骗了你。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Nein, streng genommen haben wir Sie sogar getäuscht."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Pour être tout à fait honnête, nous nous sommes servis de vous pendant tout ce temps."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EXILER_ACT1_INTERUDE2@247#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 247
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 5500107
L47_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
