L47_1.m_Face = "UNIT_DESPAIR"
L47_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L47_1.m_Pos = "L"
L48_1 = "20년 뒤 다가올 멸망을 막기 위해서."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "20年後に訪れる滅亡を食い止めるために。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "So we could prevent this world from destruction 20 years in the future."
L47_1.m_Talk_ENG = L48_1
L48_1 = "為了阻止20年後到來的滅亡。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เพราะเราต้องการป้องกันไม่ให้โลกนี้ถูกทำลายได้ในอีก 20 ปีข้างหน้าน่ะ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Để chúng tôi có thể ngăn thế giới này khỏi sự hủy diệt trong 20 năm tới."
L47_1.m_Talk_VTN = L48_1
L48_1 = "为了阻止20年后到来的灭亡。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Um die Zerstörung der Welt zu verhindern, die uns in 20 Jahren bevorsteht."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Dans le but d'empêcher la destruction de ce monde dans 20 ans."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EXILER_ACT1_INTERUDE2@248#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 248
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5500107
L48_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L48_1.m_bWaitClick = true
