L48_1.m_Face = "UNIT_IDLE"
L48_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L48_1.m_Pos = "L"
L49_1 = "그 작전으로부터 벌써 2년에 가까운 시간을 소비해버렸으니 실제로는 더 짧겠지만요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "その作戦にもう2年近くの時間を費やしましたから、実際にはもっと短いでしょうね。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "We've already used up 2 years since that operation, so it'll be less than 20 in reality."
L48_1.m_Talk_ENG = L49_1
L49_1 = "而且從那場作戰算起，已經過了將近2年的時間。實際上已經不到20年了。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "แต่เราก็ใช้เวลาแค่ 2 ปี ตั้งแต่ปฏิบัติการนั้น แต่ตามจริงมันก็ยังไม่ถึง 20 ปีอยู่ดี"
L48_1.m_Talk_THA = L49_1
L49_1 = "Chúng tôi đã sử dụng hết 2 năm kể từ lần tác chiến đó, nên thực tế nó sẽ ít hơn 20 năm."
L48_1.m_Talk_VTN = L49_1
L49_1 = "而且从那场作战算起，已经过去了近2年的时间。实际上已经不到20年了。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Seit dieser Operation sind bereits zwei Jahre vergangen, also bleiben uns sogar weniger als 20 Jahre."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Deux ans se sont déjà écoulés depuis la fin de l'opération, alors il nous reste en réalité moins de 20 ans."
L48_1.m_Talk_FRA = L49_1
