L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 251
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 5500107
L1_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L2_1 = "COMMANDER_EXILER_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "그, 그렇다면 왜 이제와서 이런 이야기를 하는 겁니까?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "な、なら、なぜ今急に私にその話をされるんですか？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Th-then why are you telling me this now?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "那，那樣的話，為什麼要現在告訴我這些？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แล้วคุณคิดยังไง ถึงได้มาบอกก่อนฉันล่ะคะ ?"
L1_1.m_Talk_THA = L2_1
L2_1 = "V-vậy sao bây giờ cô lại nói với tôi điều này?"
L1_1.m_Talk_VTN = L2_1
L2_1 = "那、那样的话，为什么要现在告诉我这些？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "W-warum erzählen Sie mir das denn jetzt?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "M-Mais pourquoi me dire ça maintenant ?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EXILER_ACT1_INTERUDE2@252#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 252
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5500107
L2_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "COMMANDER_EXILER_NULL_NULL"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "굳이 저에게 진실을 전할 필요는 없었을 텐데요?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "あえて私にその真実を明かす必要はなかったはずです。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You didn't have to tell me the truth."
L2_1.m_Talk_ENG = L3_1
L3_1 = "你沒必要告訴我真相吧？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "ที่จริงแล้วคุณเองก็ไม่จำเป็นต้องบอกกับฉันก็ได้"
L2_1.m_Talk_THA = L3_1
L3_1 = "Cô không cần phải nói với tôi sự thật."
L2_1.m_Talk_VTN = L3_1
L3_1 = "您没必要告诉我真相吧?"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Sie hätten mir doch gar nicht die Wahrheit sagen müssen."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Vous n'étiez pas obligée de me dire la vérité."
L2_1.m_Talk_FRA = L3_1
