L5_1 = "EXILER_ACT1_INTERUDE2@254#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 254
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 5500107
L4_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_IDLE"
L4_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L4_1.m_Pos = "C"
L5_1 = "저는 여전히 당신이 어디서 왔는지, 누구인지, 어떤 목적을 가졌는지 모릅니다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "私は相変わらずあなたがどこから来たのか、何者なのか、どんな目的があるのか、わかりません。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "I still don't know where you're from, who you are, or what intentions you had when you came here."
L4_1.m_Talk_ENG = L5_1
L5_1 = "我不知道你來自哪裡，你是誰，有什麼樣的目的。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ใช้แล้ว เพราะจริงๆ พวกเราเองก็ไม่รู้ว่าเธอมาจากที่ไหน เธอเป็นใคร หรือมีความตั้งใจอะไรกันแน่ ที่มาที่นี่"
L4_1.m_Talk_THA = L5_1
L5_1 = "Tôi vẫn không biết cô đến từ đâu, cô là ai, hay cô có ý định gì khi đến đây."
L4_1.m_Talk_VTN = L5_1
L5_1 = "我不知道你来自哪里，你是谁，有什么样的目的。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Ich weiß immer noch nicht, woher Sie kommen, wer Sie sind oder welche Absichten Sie hatten, als Sie hierherkamen."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Je ne sais toujours pas d'où vous venez, qui vous êtes, ni quelles intentions vous aviez lorsque vous êtes venue ici."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EXILER_ACT1_INTERUDE2@255#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 255
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5500107
L5_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L5_1.m_Pos = "C"
L6_1 = "하지만 지난 1년, 당신을 지켜본 결과 한 가지는 확신할 수 있었어요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ですが、この1年間あなたを見てきて、一つだけは確信できました。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "But after observing you for the past year, I became certain of one thing."
L5_1.m_Talk_ENG = L6_1
L6_1 = "但根據過去1年的時間裡對你的觀察，我可以確信一點。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "แต่จากที่ฉันได้สังเกตเฝ้าดูเธอมาหลายปี ฉันก็ค่อนข้างมั่นใจสิ่งหนึ่ง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Nhưng sau khi quan sát trong một năm qua, tôi đã chắc chắn một điều."
L5_1.m_Talk_VTN = L6_1
L6_1 = "但根据过去1年时间里对你的观察，我可以确信一点。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Aber nachdem ich Sie das letzte Jahr über beobachtet habe, bin ich mir einer Sache sicher."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Mais après vous avoir observée au cours de la dernière année, je suis devenue certaine d'une chose."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
