L6_1.m_Pos = "C"
L6_1.m_Crash = 20
L7_1 = "당신은 역시 틀림없는 델타 세븐의 일원이에요."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あなたは間違いなくデルタセブンの一員です。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You are, without a doubt, a member of Delta Seven."
L6_1.m_Talk_ENG = L7_1
L7_1 = "你一定也是第七三角洲部隊的一員。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "นั่นคือ..เธอต้องเป็นสมาชิกของเดลต้าเซเว่นจริงๆ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Không còn nghi ngờ gì nữa, cô là một thành viên của Delta Seven."
L6_1.m_Talk_VTN = L7_1
L7_1 = "你一定也是德尔塔部队的一员。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Sie sind ohne Zweifel ein Mitglied von Delta Seven."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Vous êtes sans l'ombre d'un doute un membre de Delta Seven."
L6_1.m_Talk_FRA = L7_1
