L10_1.m_Face = "UNIT_IDLE"
L10_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L10_1.m_Pos = "L"
L11_1 = "그리고 저는 <color=#ffd34c>동료</color>라고 생각하는 사람을 속일 생각은 없습니다."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "そして私は、<color=#ffd34c>仲間</color>だと思う人を騙すつもりはありません。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "And I have no intention of deceiving someone I consider a <color=#ffd34c>comrade</color>."
L10_1.m_Talk_ENG = L11_1
L11_1 = "而且，我把你當成<color=#ffd34c>夥伴</color>，所以我不想欺騙你。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "แล้วฉันเองก็คงปิดบังคนที่ฉันเรียกว่า <color=#ffd34c>สหาย</color>ไม่ได้"
L10_1.m_Talk_THA = L11_1
L11_1 = "Và tôi không có ý định lừa dối một người mà tôi coi là <color=#ffd34c>đồng chí</color>."
L10_1.m_Talk_VTN = L11_1
L11_1 = "而且，我把你当做了<color=#ffd34c>同伴</color>，所以我不想欺骗你。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Und ich habe nicht die Absicht, jemanden zu täuschen, den ich als <color=#ffd34c>Kameraden</color> betrachte."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Et je n'ai nullement l'intention de tromper quelqu'un que je considère comme un <color=#ffd34c>camarade</color>."
L10_1.m_Talk_FRA = L11_1
