L14_1 = "EXILER_ACT1_INTERUDE2@263#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 263
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 5500107
L13_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_IDLE"
L13_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L13_1.m_Pos = "C"
L14_1 = "하지만 기억이 없는 당신에게 제 생각을 강요할 생각도 없죠."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "同時に、記憶の無いあなたに私の意思を強要するつもりもありません。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "But I don't want to force my thoughts on someone who has no recollection of herself."
L13_1.m_Talk_ENG = L14_1
L14_1 = "但我不會將我的想法強加於失憶的你身上。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฉันไม่อยากบังคับเธอหรือสั่งเธอ ขณะที่เธอยังจำตัวเองไม่ได้"
L13_1.m_Talk_THA = L14_1
L14_1 = "Nhưng tôi không muốn áp đặt suy nghĩ của mình lên một người không có hồi ức về bản thân."
L13_1.m_Talk_VTN = L14_1
L14_1 = "但我不会将我的想法强加于失忆的你身上。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Aber ich habe auch nicht die Absicht, jemandem, der sich nicht einmal an sich selbst erinnern kann, meine Meinung aufzuzwingen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Mais je ne veux pas imposer mes idées à quelqu'un qui a perdu la mémoire."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EXILER_ACT1_INTERUDE2@264#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 264
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5500107
L14_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "UNIT_LAUGH"
L14_1.m_Face = L15_1
L14_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L14_1.m_Pos = "C"
L14_1.m_Crash = 10
L15_1 = "그러니 선택은 당신의 몫입니다, 안토노프."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "選択はあなた次第です、アントノフ。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "So, the choice is up to you, Antonov."
L14_1.m_Talk_ENG = L15_1
L15_1 = "選擇權在你手上，安東諾夫。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ดังนั้น แอนโทนอฟ เธอมีทางเลือกมันขึ้นอยู่กับเธอแล้ว  "
L14_1.m_Talk_THA = L15_1
L15_1 = "Vì vậy, sự lựa chọn là tùy thuộc vào cô, Antonov."
L14_1.m_Talk_VTN = L15_1
L15_1 = "选择权在你手上，安东。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Die Wahl liegt also bei Ihnen, Antonow."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Le choix dépend donc de vous, Antonov."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EXILER_ACT1_INTERUDE2@265#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 265
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 5500107
L15_1.m_CutScenStrID = "EXILER_ACT1_INTERUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Face = "UNIT_IDLE"
L15_1.m_CharStrID = "KYLE_DELTA_AP_NULL"
L15_1.m_Pos = "C"
L16_1 = "군복을 벗고 남은 시간을 자유롭게 살 지, 아니면 우리와 함께 끝까지 싸울 지."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "軍から離れて残りの時間を自由に過ごすか、最後まで私たちと共に戦うか。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Will you take off the uniform and live a free life, or will you fight alongside us until the bitter end?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "褪去軍裝，剩下的時間裡自由地生活，還是和我們一起並肩作戰到最後？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "เธออยากจะถอดเครื่องแบบออก และออกไปใช้ชีวิตอย่างอิสระก็ได้ หรือว่าเธออยากจะสู้ต่อไปพร้อมกับเราก็ได้?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Cô sẽ cởi bỏ bộ đồng phục và sống một cuộc sống tự do, hay sẽ chiến đấu cùng chúng tôi cho đến cuối cùng?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "褪去军装，剩下的时间里自由地生活，还是和我们一起并肩作战到最后？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Werden Sie diese Uniform ablegen und ein freies Leben führen oder werden Sie bis zum bitteren Ende an unserer Seite kämpfen?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Allez-vous retirer votre uniforme et vivre une vie libre, ou allez-vous vous battre à nos côtés jusqu'à la fin amère qui nous attend ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
