L20_1 = "긴급 상황? 하루에 두 번씩이나?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "緊急事態？　一日に二度も？"
L19_1.m_Talk_JPN = L20_1
L20_1 = "An emergency? Twice in one day?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "緊急狀況？今天發生的第二起嗎？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "ฉันต้องเลือกวันนี้หรอค่ะ? ขอฉันกลับไปคิดดูก่อนนะคะ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Trường hợp khẩn cấp? Hai lần trong một ngày sao?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "紧急状况？今天发生的第二起吗？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Ein Notfall? Zweimal an einem Tag?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Une situation d'urgence ? Deux fois en une journée ?"
L19_1.m_Talk_FRA = L20_1
