L21_1.m_Pos = "L"
L22_1 = "당장 이 자리에서 선택하라는 건 아닙니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "今すぐこの場で決めろとは言いません。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "I'm not asking you to answer right now."
L21_1.m_Talk_ENG = L22_1
L22_1 = "你不用馬上做出抉擇。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เธอไม่ต้องรีบให้คำตอบเรา  "
L21_1.m_Talk_THA = L22_1
L22_1 = "Tôi không yêu cầu cô trả lời ngay bây giờ."
L21_1.m_Talk_VTN = L22_1
L22_1 = "你不用马上做出抉择。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ich erwarte nicht, dass Sie jetzt sofort Ihre Wahl zu treffen."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Je ne vous demande pas de répondre maintenant."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
