L23_1 = "하지만 마음의 준비가 된다면 언제든 제게 말씀해주세요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "ですが、心の準備ができたら、いつでも私に言ってください。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "But please do whenever you are ready."
L22_1.m_Talk_ENG = L23_1
L23_1 = "但你要是準備好了，隨時可以跟我說。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เมื่อไหร่ที่เธอพร้อม ค่อยบอกเรา"
L22_1.m_Talk_THA = L23_1
L23_1 = "Nhưng hãy trả lời khi nào cô sẵn sàng."
L22_1.m_Talk_VTN = L23_1
L23_1 = "但你要是准备好了，随时可以跟我说。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Aber bitte tun Sie es, wann immer Sie dazu bereit sind."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Dites-le moi quand vous serez prête."
L22_1.m_Talk_FRA = L23_1
